    const adjRows=adjustments.map(a=>`<tr><td>${e(a.adjustment_date)}</td><td>${tr(a.adjustment_type)}</td><td>${tr(a.effect)}</td><td>${fmt(a.amount_krw)}</td><td>${e(a.reference)}</td><td>${e(a.notes||'')}</td></tr>`).join('');
    const position=accountPosition313(c.account_balance_krw);
    openWorkflowHtmlV324(`<div class="section-title"><div><h2>${e(c.name)} · ${tr('Account')}</h2><div class="muted">${tr('Customer / Store account, credit terms, aging, pricing and payment history.')}</div></div><div class="ps313-inline"><button class="btn" onclick="psStatement313(${id})">${tr('Statement')}</button><button class="btn primary" onclick="psReceiptForm313(${id})">+ ${tr('Record Payment / Settlement')}</button></div></div><div class="ps313-account-head"><div><small>${tr('Outstanding')}</small><b>${fmt(c.outstanding_krw)}</b></div><div><small>${tr('Overdue')}</small><b>${fmt(c.overdue_krw)}</b></div><div><small>${tr('Unallocated Credit')}</small><b>${fmt(c.unallocated_credit_krw)}</b></div><div><small>${tr('Account Position')}</small><b class="${position.className}">${tr(position.label)} · ${fmt(position.amount)}</b></div></div><h3>${tr('Aging')}</h3><div class="ps313-aging"><div><small>${tr('Current')}</small><b>${fmt(d.aging.current)}</b></div><div><small>${tr('1–30 Days')}</small><b>${fmt(d.aging.d1_30)}</b></div><div><small>${tr('31–60 Days')}</small><b>${fmt(d.aging.d31_60)}</b></div><div><small>${tr('61–90 Days')}</small><b>${fmt(d.aging.d61_90)}</b></div><div><small>${tr('90+ Days')}</small><b>${fmt(d.aging.d90_plus)}</b></div></div><div class="card" style="margin-top:12px"><div class="section-title"><h3>${tr('Account Terms')}</h3></div><form onsubmit="psSaveAccountTerms313(event,${id})"><div class="grid g4"><div class="field"><label>${tr('Pricing Tier')}</label><select name="pricing_tier">${['Retail','Wholesale','Distributor','E-commerce','Special Contract'].map(x=>`<option value="${e(x)}" ${x===c.pricing_tier?'selected':''}>${tr(x)}</option>`).join('')}</select></div><div class="field"><label>${tr('Credit Terms (Days)')}</label><input name="credit_terms_days" type="number" min="0" step="1" value="${Number(c.credit_terms_days||0)}"></div><div class="field"><label>${tr('Credit Limit (KRW)')}</label><input name="credit_limit_krw" type="number" min="0" step="1" value="${Number(c.credit_limit_krw||0)}"></div><div class="field"><label>${tr('Statement Currency')}</label><select name="statement_currency"><option value="KRW" ${c.statement_currency==='KRW'?'selected':''}>KRW</option><option value="USD" ${c.statement_currency==='USD'?'selected':''}>USD</option><option value="PKR" ${c.statement_currency==='PKR'?'selected':''}>PKR</option></select></div></div><div class="actions"><button class="btn primary">${tr('Save Account Terms')}</button></div></form></div><div class="ps313-tabs"><button class="btn active" data-ps313-tab="orders" onclick="psAccountTab313(this,'orders')">${tr('Order Receivables')}</button><button class="btn" data-ps313-tab="receipts" onclick="psAccountTab313(this,'receipts')">${tr('Receipts / Settlements')}</button><button class="btn" data-ps313-tab="prices" onclick="psAccountTab313(this,'prices')">${tr('Customer Pricing')}</button><button class="btn" data-ps313-tab="adjust" onclick="psAccountTab313(this,'adjust')">${tr('Adjustments / Credit Notes')}</button></div><div data-ps313-pane="orders"><div class="table-wrap"><table class="table"><tr><th>${tr('Order No.')}</th><th>${tr('Due Date')}</th><th>${tr('Total')}</th><th>${tr('Paid')}</th><th>${tr('Outstanding')}</th><th>${tr('Payment Status')}</th><th></th></tr>${orderRows||`<tr><td colspan="7"><div class="empty">${tr('No outstanding completed orders.')}</div></td></tr>`}</table></div></div><div data-ps313-pane="receipts" style="display:none"><div class="table-wrap"><table class="table"><tr><th>${tr('Date')}</th><th>${tr('Reference')}</th><th>${tr('Cash Received')}</th><th>${tr('Settlement Fee (KRW)')}</th><th>${tr('Gross Settlement')}</th><th>${tr('Allocated')}</th><th>${tr('Remaining Credit')}</th><th></th></tr>${receiptRows||`<tr><td colspan="8"><div class="empty">${tr('No receipts recorded.')}</div></td></tr>`}</table></div></div><div data-ps313-pane="prices" style="display:none"><div class="section-title"><h3>${tr('Customer Pricing')}</h3><button class="btn primary small" onclick="psCustomerPriceForm313(${id})">+ ${tr('Add Customer Price')}</button></div><p class="muted">${tr('Customer-specific price → pricing tier → product default → authorized manual override.')}</p><div class="table-wrap"><table class="table"><tr><th>${tr('Finished Product')}</th><th>${tr('Unit Price (KRW)')}</th><th>${tr('Minimum Quantity')}</th><th>${tr('Effective Dates')}</th><th>${tr('Status')}</th></tr>${priceRows||`<tr><td colspan="5"><div class="empty">${tr('No customer-specific prices.')}</div></td></tr>`}</table></div></div><div data-ps313-pane="adjust" style="display:none"><div class="section-title"><h3>${tr('Adjustments / Credit Notes')}</h3><button class="btn primary small" onclick="psAdjustmentForm313(${id})">+ ${tr('Add Adjustment')}</button></div><div class="table-wrap"><table class="table"><tr><th>${tr('Date')}</th><th>${tr('Type')}</th><th>${tr('Effect')}</th><th>${tr('Amount')}</th><th>${tr('Reference')}</th><th>${tr('Notes')}</th></tr>${adjRows||`<tr><td colspan="6"><div class="empty">${tr('No adjustments.')}</div></td></tr>`}</table></div></div><div class="actions"><button class="btn" onclick="closeModal()">${tr('Close')}</button></div>`, 'wide');translateElement(workflowSurfaceV324());
