  window.psAccountTab313=function(btn,name){const root=workflowSurfaceV324();root.querySelectorAll('[data-ps313-tab]').forEach(x=>x.classList.toggle('active',x===btn));root.querySelectorAll('[data-ps313-pane]').forEach(x=>x.style.display=x.dataset.ps313Pane===name?'':'none')};
