  window.psPriceTiers313=async function(){const [tiers,products]=await Promise.all([api('/api/pink-salt/price-tiers-v313'),api('/api/pink-salt/products')]);window.__ps313Products=products.filter(x=>x.active);modal(`<h2>${tr('Price Tiers')}</h2><p class="muted">${tr('Customer-specific price → pricing tier → product default → authorized manual override.')}</p>${tiers.map(tier=>`<div class="card" style="margin-bottom:10px"><div class="section-title"><div><h3>${tr(tier.name)}</h3><div class="muted">${tr(tier.description||'')}</div></div><button class="btn small primary" onclick="psTierPriceForm313(${tier.id},'${e(tier.name).replaceAll("'","\\'")}')">+ ${tr('Add Tier Price')}</button></div><div class="table-wrap"><table class="table"><tr><th>${tr('Finished Product')}</th><th>${tr('Unit Price (KRW)')}</th><th>${tr('Minimum Quantity')}</th><th>${tr('Effective Dates')}</th></tr>${(tier.items||[]).map(x=>`<tr><td>${e(x.sku)} · ${e(x.product_name)}</td><td>${fmt(x.unit_price_krw)}</td><td>${x.min_quantity}</td><td>${e(x.effective_from||'—')} → ${e(x.effective_to||'—')}</td></tr>`).join('')||`<tr><td colspan="4"><div class="empty">${tr('No records.')}</div></td></tr>`}</table></div></div>`).join('')}<div class="actions"><button class="btn" onclick="closeModal()">${tr('Close')}</button></div>`, 'wide');translateElement(document.getElementById('modalRoot'))};
