  window.ps313LineChanged=async function(i,k,v){const x=window.__ps313Lines[i];if(!x)return;x[k]=k==='quantity_units'?Math.max(1,Math.trunc(Number(v||1))):v;if(k==='product_id'||k==='quantity_units')await ps313PriceLine(i);else ps313DrawLines()};
  window.ps313PriceLine=async function(i){const x=window.__ps313Lines[i],f=document.querySelector('#v324WorkflowSurface form')||document.querySelector('#modalRoot form');if(!x?.product_id||!f)return;const q=new URLSearchParams({product_id:x.product_id,quantity:x.quantity_units||1,date:f.order_date.value||iso()});if(f.customer_id.value)q.set('customer_id',f.customer_id.value);const p=await api('/api/pink-salt/pricing-v313/context?'+q.toString());x.suggested_price_krw=Number(p.unit_price_krw||0);x.unit_price_krw=x.suggested_price_krw;x.pricing_source=p.pricing_source;x.price_override_reason='';ps313DrawLines()};
