  const VERSION='30.15.0',n=v=>Number(v||0),fmt=v=>'₩ '+n(v).toLocaleString('en-US',{maximumFractionDigits:0}),e=v=>esc(String(v??'')),iso=()=>new Date().toISOString().slice(0,10),tr=x=>esc(t(x));
  const psSelected=()=>unitOptions?.find(x=>String(x.id)===String(selectedUnitId))?.name==='Pink Salt';
  const supplierTypes=['Import / Raw Salt Supplier','Packaging Material Supplier'];
