  const style=document.createElement('style');style.id='v315-ui';style.textContent=`.ps315-filterbar{display:grid;grid-template-columns:2fr 1.2fr 1.2fr 1fr;gap:9px;margin-bottom:12px}.ps315-kpis,.ps315-aging{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.ps315-aging{grid-template-columns:repeat(5,minmax(0,1fr))}.ps315-kpis>div,.ps315-aging>div{padding:13px;border:1px solid var(--line);border-radius:12px;background:#fff}.ps315-kpis small,.ps315-aging small{display:block;color:var(--muted);font-weight:700}.ps315-kpis b,.ps315-aging b{display:block;margin-top:5px;font-size:17px}.ps315-kpis .available,.ps315-kpis .good{background:#f0fff7;border-color:#a7dfc2}.ps315-kpis .warn{background:#fff8e9;border-color:#efd59a}.ps315-tabs{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.ps315-history-detail{max-width:520px;white-space:normal;word-break:break-word}.ps-mini{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid var(--line)}.ps-mini small{display:block;color:var(--muted);margin-top:3px}.ps315-two{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}.ps315-checks{display:flex;flex-wrap:wrap;gap:12px;padding:12px;border:1px solid var(--line);border-radius:10px}.ps315-checks label{display:flex;align-items:center;gap:6px}.ps315-creditbox{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 14px;border:1px solid #b9d1ed;background:#f5f9ff;border-radius:12px;margin:10px 0}.ps315-creditbox span{display:block;color:var(--muted);font-size:12px;margin-top:3px}@media(max-width:900px){.ps315-filterbar,.ps315-kpis,.ps315-aging,.ps315-two{grid-template-columns:1fr 1fr}}@media(max-width:620px){.ps315-filterbar,.ps315-kpis,.ps315-aging,.ps315-two{grid-template-columns:1fr}.ps315-creditbox{align-items:flex-start;flex-direction:column}}`;document.head.appendChild(style);
