      const sensitiveRows=[...catalog.sensitive,...catalog.delegated].map(key=>{const effect=fmtPermissionEffect(data.overrides,key,bu),label=SENSITIVE_LABELS[key]||DELEGATED_LABELS[key]||key,editable=accessControlEditable(canManage,key);return `<div class="access-right-card ${effect==='Allow'?'access-allow':effect==='Deny'?'access-deny':''}"><div class="section-title"><b>${esc(t(label))}</b><select data-access-special="${esc(key)}" ${editable?'':'disabled'}>${optionEffects(effect)}</select></div><div class="muted" data-no-i18n>${esc(key)}</div></div>`}).join('');
