async function v319RenderMigrations(panel,row,meta){
  const [types,jobs]=await Promise.all([api('/api/system-settings-v319/migrations/types'),api('/api/system-settings-v319/migrations').catch(()=>[])]),canEdit=!!row.can_edit;
  panel.innerHTML=`<section class="card"><div class="section-title"><div><h2>Data Migration & Bulk Import</h2><div class="muted">Upload → Validate → Preview / Map → Resolve → Review & Confirm → Import. Live records are never silently overwritten.</div></div>${canEdit?'<button class="btn primary" onclick="v319MigrationUpload()">+ New Migration</button>':''}</div><div class="grid g3">${types.map(tp=>`<div class="card"><b>${esc(tp.label)}</b><div class="muted">${tp.staging_only?'Staging only · Accounting review required':'Validated live import supported'}</div><a class="btn small" href="/api/system-settings-v319/migrations/template/${encodeURIComponent(tp.key)}" download>Download Template</a></div>`).join('')}</div><div class="table-wrap" style="margin-top:14px"><table class="table"><tr><th>Migration ID</th><th>Type</th><th>BU</th><th>Rows</th><th>Status</th><th>Actions</th></tr>${jobs.map(j=>`<tr><td><b>${esc(j.migration_no)}</b><div class="muted">${esc(j.original_name)}</div></td><td>${esc(types.find(x=>x.key===j.migration_type)?.label||j.migration_type)}</td><td>${esc(j.business_unit||'')}</td><td>${j.total_rows} · Valid ${j.valid_rows} · Errors ${j.error_rows}</td><td><span class="pill ${j.status==='Imported'?'good':j.error_rows?'bad':'warn'}">${esc(j.status)}</span></td><td><div class="v319-doc-actions"><button class="btn small" onclick="v319MigrationDetail(${j.id})">Preview</button>${canEdit&&!['Imported','Cancelled'].includes(j.status)?`<button class="btn small primary" onclick="v319ValidateMigration(${j.id})">Validate</button>${j.status==='Validated'?`<button class="btn small primary" onclick="v319ImportMigration(${j.id},${JSON.stringify(j.migration_no)})">Import</button>`:''}<button class="btn small danger" onclick="v319CancelMigration(${j.id},${JSON.stringify(j.migration_no)})">Cancel</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6">No migration jobs.</td></tr>'}</table></div></section>`;translateElement(panel);window._v319MigrationTypes=types
}
window.v319MigrationUpload=async function(){const types=window._v319MigrationTypes||await api('/api/system-settings-v319/migrations/types'),units=await api('/api/business-units');modal(`<h2>New Data Migration</h2><form onsubmit="saveMigrationUploadV319(event)" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Migration Type *</label><select name="migration_type" required>${types.map(x=>`<option value="${x.key}">${esc(x.label)}</option>`).join('')}</select></div><div class="field"><label>Business Unit *</label><select name="business_unit_id" required>${units.map(u=>`<option value="${u.id}" ${Number(u.id)===Number(selectedUnitId)?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div></div><div class="field"><label>Excel / CSV *</label><input name="file" type="file" accept=".xlsx,.csv" required></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Upload to Staging</button></div></form>`,'wide')};
window.saveMigrationUploadV319=async function(e){e.preventDefault();try{const r=await multipartApi('/api/system-settings-v319/migrations/upload',new FormData(e.target));closeModal(true);toast(`Migration ${r.migration_no} uploaded · ${r.total_rows} row(s)`);await v319MigrationDetail(r.id)}catch(x){toast(x.message)}};
window.v319MigrationDetail=async function(id){try{const d=await api('/api/system-settings-v319/migrations/'+id),fields=Object.keys(d.job.mapping||{});modal(`<div class="section-title"><div><h2>${esc(d.job.migration_no)}</h2><div class="muted">${esc(d.job.original_name)} · ${esc(d.job.status)}</div></div><button class="btn" onclick="closeModal()">✕</button></div><div class="card"><b>Field Mapping</b><div class="muted">${esc(fields.map(k=>k+' ← '+d.job.mapping[k]).join(' · ')||'No mapping detected')}</div></div><div class="table-wrap"><table class="table"><tr><th>Row</th><th>Status</th><th>Normalized Data</th><th>Errors / Warnings</th></tr>${d.rows.slice(0,200).map(r=>`<tr><td>${r.row_no}</td><td><span class="pill ${r.status==='Valid'?'good':r.status==='Error'?'bad':'warn'}">${esc(r.status)}</span></td><td><small>${esc(JSON.stringify(r.normalized))}</small></td><td><small>${esc([...(r.errors||[]),...(r.warnings||[])].join(' · '))}</small></td></tr>`).join('')}</table></div><div class="actions"><button class="btn" onclick="closeModal()">Close</button><button class="btn primary" onclick="closeModal(true);v319ValidateMigration(${id})">Validate</button></div>`,'wide')}catch(x){toast(x.message)}};
window.v319ValidateMigration=async function(id){try{const r=await api('/api/system-settings-v319/migrations/'+id+'/validate',{method:'POST'});toast(`${r.status} · Valid ${r.valid_rows} · Errors ${r.error_rows}`);await v319RenderSettingsPanel()}catch(x){toast(x.message)}};
window.v319ImportMigration=async function(id,no){const reason=await reasonAction({title:'Review & Confirm Migration Import',message:'Validated staging rows will be committed to live operational tables. Existing records are not silently overwritten.',confirmLabel:'Import Validated Rows',tone:'danger',details:[{label:'Migration ID',value:no}]});if(reason===null)return;try{const r=await api('/api/system-settings-v319/migrations/'+id+'/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm_import:true,reason})});toast(`${r.migration_no}: ${r.imported_rows} row(s) imported`);await v319RenderSettingsPanel()}catch(x){toast(x.message)}};
window.v319CancelMigration=async function(id,no){const reason=await reasonAction({title:'Cancel Migration',message:'Staging data will remain in audit history but will not be imported.',confirmLabel:'Cancel Migration',tone:'danger',details:[{label:'Migration ID',value:no}]});if(reason===null)return;try{await api('/api/system-settings-v319/migrations/'+id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast('Migration cancelled');await v319RenderSettingsPanel()}catch(x){toast(x.message)}};

function v3252ResetCard(status,canEdit){
  if(!status)return '';
  const list=status.pre_reset_backups||[],latest=status.latest_backup;
  const envOk=!!status.enabled;
  return `<section class="card" style="margin-top:12px;border-color:${envOk?'#f0c9c9':'var(--line)'}"><div class="section-title"><div><h3>Development / Test Environment Reset</h3><div class="muted">Safely wipe test data without detaching the Render persistent disk. Every reset creates a database + uploads snapshot first, and only the newest ${Number(status.retention||3)} pre-reset backups are retained.</div></div><span class="pill ${envOk?'warn':''}">${envOk?'DEV / TEST RESET ENABLED':'Disabled'}</span></div>${envOk?`<div class="workspace-banner" style="margin-bottom:12px"><b>Development / testing service only</b><span>Guarded by APP_ENV=development or testing + ALLOW_TEST_DATA_RESET=true + authorized user + current password + typed confirmation. Never enable these flags on Production.</span></div><div class="grid g4"><div class="card stat"><small>Database</small><b>${fileSizeV319(status.database_bytes||0)}</b></div><div class="card stat"><small>Uploads</small><b>${fileSizeV319(status.upload_bytes||0)}</b><small>${Number(status.upload_files||0)} file(s)</small></div><div class="card stat"><small>Operational Records</small><b>${Number(status.operational_rows||0)}</b></div><div class="card stat"><small>Pre-reset Retention</small><b>${Number(status.retention||3)}</b><small>automatic snapshots</small></div></div>${canEdit?`<div class="actions" style="margin-top:14px"><button class="btn" onclick="v3252ResetDialog('quick')">Quick Reset</button><button class="btn danger" onclick="v3252ResetDialog('full')">Full Clean Reset</button><button class="btn danger" onclick="v3252ResetDialog('full-demo')">Full Reset + Demo</button><button class="btn" ${status.clear_uploads_allowed?'':'disabled title="Operational records still reference uploads"'} onclick="v3252ResetDialog('clear-uploads')">Clear Uploads Only</button><button class="btn primary" ${latest?'':'disabled'} onclick="v3252ResetDialog('restore-last')">Restore Last Pre-Reset Backup</button></div>`:''}<div class="muted" style="margin-top:10px"><b>Quick Reset</b> keeps users/access, BUs, System Settings, approval rules, COA/company financial accounts and numbering configuration; it clears operational/test transactions, sequences and uploads. <b>Full Reset</b> rebuilds a fresh database and clears uploads while preserving the pre-reset backup folder on the persistent disk.</div>`:`<div class="v319-evidence-note"><b>Reset controls are intentionally unavailable.</b> Current APP_ENV: ${esc(status.app_env||'(not set)')}. To use this on the dedicated Render development/testing service, set <code>APP_ENV=development</code> (or <code>testing</code>) and <code>ALLOW_TEST_DATA_RESET=true</code>. Do not set these on Production.</div>`}<h3 style="margin-top:16px">Automatic Pre-reset Backups</h3><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Operation</th><th>Database</th><th>Uploads</th><th>Reason</th></tr>${list.map(b=>`<tr><td>${esc(b.created_at||'')}</td><td>${esc(b.operation||'')}</td><td>${fileSizeV319(b.database_bytes||0)}</td><td>${fileSizeV319(b.upload_bytes||0)} · ${Number(b.upload_files||0)} file(s)</td><td>${esc(b.reason||'')}</td></tr>`).join('')||'<tr><td colspan="5">No automatic pre-reset backup yet.</td></tr>'}</table></div></section>`;
}
async function v319RenderMaintenance(panel,row,meta){const st=v319ScopeState(),[backups,diag,resetStatus]=await Promise.all([api('/api/system-settings-v319/backups').catch(()=>[]),api('/api/system-settings-v319/attachment-diagnostics').catch(()=>null),api('/api/system-settings-v3252/test-reset/status').catch(()=>null)]);panel.innerHTML=v319GenericFormHtml(st,row,meta)+`<section class="card" style="margin-top:12px"><div class="section-title"><div><h3>Backup / Storage / Maintenance</h3><div class="muted">Backups are file-system copies for the configured SQLite database. Render testing uses the attached persistent disk; Production backup policy should remain separate.</div></div>${row.can_edit?'<button class="btn primary" onclick="v319CreateBackup()">Create Backup Now</button>':''}</div>${diag?`<div class="grid g3"><div class="card stat"><small>Attachment Storage</small><b>${fileSizeV319(diag.storage_usage_bytes)}</b></div><div class="card stat"><small>Files</small><b>${diag.file_count}</b></div><div class="card stat"><small>Potential Orphans</small><b>${diag.orphan_count}</b></div></div>`:''}<h3 style="margin-top:14px">Backup History</h3><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Backup</th><th>Size</th><th>Status</th><th>Reason</th></tr>${backups.map(b=>`<tr><td>${esc(b.created_at)}</td><td>${esc(b.backup_name)}</td><td>${fileSizeV319(b.size_bytes)}</td><td>${esc(b.status)}</td><td>${esc(b.reason||'')}</td></tr>`).join('')||'<tr><td colspan="5">No backup history.</td></tr>'}</table></div></section>${v3252ResetCard(resetStatus,!!row.can_edit)}`;translateElement(panel)}
// V30.26.3: scrub any legacy reset-form credentials that an older native GET submit may have leaked into the current URL.
try{const u=new URL(location.href);if(['password','reason','confirmation'].some(k=>u.searchParams.has(k))){history.replaceState(history.state,'',u.pathname+u.hash)}}catch(_){ }

function v3252ResetConfig(action){return {
  quick:{endpoint:'/api/system-settings-v3252/test-reset/quick',label:'Quick Reset',phrase:'RESET TEST DATA'},
  full:{endpoint:'/api/system-settings-v3252/test-reset/full',label:'Full Clean Reset',phrase:'RESET TEST DATA'},
  'full-demo':{endpoint:'/api/system-settings-v3252/test-reset/full-demo',label:'Full Reset + Demo',phrase:'RESET TEST DATA'},
  'clear-uploads':{endpoint:'/api/system-settings-v3252/test-reset/clear-uploads',label:'Clear Uploads',phrase:'RESET TEST DATA'},
  'restore-last':{endpoint:'/api/system-settings-v3252/test-reset/restore-last',label:'Restore Last Pre-Reset Backup',phrase:'RESTORE TEST BACKUP'}
}[action]||null}
window.__v3252ResetBusy=false;
window.v3252ResetDialog=function(action){
  const cfg={
    quick:{title:'Quick Test Reset',phrase:'RESET TEST DATA',button:'Reset Test Transactions',note:'Keeps users, access, business units and core configuration. Clears test operations/transactions and uploads.'},
    full:{title:'Full Clean Test Reset',phrase:'RESET TEST DATA',button:'Full Clean Reset',note:'Creates a pre-reset backup, then restarts with a fresh SQLite database and empty uploads. ADMIN_EMAIL / ADMIN_PASSWORD must be configured.'},
    'full-demo':{title:'Full Reset + Demo Users/Data',phrase:'RESET TEST DATA',button:'Reset + Seed Demo',note:'Same as Full Reset, then seeds configured demo users/data for this startup. DEMO_USER_PASSWORD must be configured.'},
    'clear-uploads':{title:'Clear Test Uploads',phrase:'RESET TEST DATA',button:'Clear Uploads',note:'Allowed only when no operational records remain, preventing broken attachment references.'},
    'restore-last':{title:'Restore Last Pre-Reset Backup',phrase:'RESTORE TEST BACKUP',button:'Restore Last Backup',note:'Creates a safety snapshot of the current test state, then restarts and restores both the database and uploads from the latest prior pre-reset backup.'}
  }[action];if(!cfg)return;
  const formId=`v3252ResetForm-${String(action).replace(/[^a-z0-9-]/gi,'')}`;
  modal(`<div class="section-title"><div><h2>${esc(cfg.title)}</h2><div class="muted">${esc(cfg.note)}</div></div><button class="btn" type="button" onclick="closeModal()">✕</button></div><div class="v319-evidence-note" style="margin-bottom:12px"><b>Protected destructive action</b><span>A pre-reset backup is created automatically. Only 2–3 newest automatic reset backups are retained according to the configured test retention.</span></div><form id="${esc(formId)}" method="post" action="javascript:void(0)" autocomplete="off"><div class="field"><label>Reason *</label><textarea name="reason" required placeholder="Why are you resetting this test environment?"></textarea></div><div class="grid g2"><div class="field"><label>Current Password *</label><input name="password" type="password" autocomplete="current-password" required></div><div class="field"><label>Type ${esc(cfg.phrase)} *</label><input name="confirmation" autocomplete="off" required placeholder="${esc(cfg.phrase)}"></div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="button" class="btn danger" data-v3252-reset-submit>${esc(cfg.button)}</button></div></form>`,'wide');
  const f=document.getElementById(formId),btn=f?.querySelector('[data-v3252-reset-submit]');
  if(!f||!btn){toast('Reset form could not be initialized. Reload the page and try again.');return}
  const run=e=>{if(e){e.preventDefault();e.stopPropagation()}if(typeof f.reportValidity==='function'&&!f.reportValidity())return false;window.v3252RunReset(f,action);return false};
  f.addEventListener('submit',run);
  btn.addEventListener('click',run);
};
window.v3252SubmitResetFromButton=function(action,formId){const f=document.getElementById(formId);if(!f)return false;if(typeof f.reportValidity==='function'&&!f.reportValidity())return false;return window.v3252RunReset(f,action)};
window.v3252SubmitReset=function(e,action){if(e){e.preventDefault();e.stopPropagation()}const f=e?.currentTarget||e?.target;if(!f)return false;window.v3252RunReset(f,action);return false};
window.v3252RunReset=async function(f,action){
  if(window.__v3252ResetBusy)return false;
  const cfg=v3252ResetConfig(action);if(!cfg)return false;
  const payload={reason:String(f.elements?.reason?.value||'').trim(),password:String(f.elements?.password?.value||''),confirmation:String(f.elements?.confirmation?.value||'').trim()};
  if(!payload.reason){toast('Reset reason is required.');f.elements?.reason?.focus();return false}
  if(!payload.password){toast('Current password is required.');f.elements?.password?.focus();return false}
  if(payload.confirmation!==cfg.phrase){toast(`Type ${cfg.phrase} exactly to continue.`);f.elements?.confirmation?.focus();return false}
  const ok=await confirmAction({title:cfg.label,message:'This action changes the dedicated TEST environment. A pre-reset snapshot is created first and old reset snapshots are pruned automatically.',confirmLabel:cfg.label,tone:'danger',details:[{label:'Reason',value:payload.reason},{label:'Environment',value:'Development / testing only'}]});if(!ok)return false;
  const btn=f.querySelector('[data-v3252-reset-submit]');window.__v3252ResetBusy=true;if(btn)btn.disabled=true;
  try{
    const r=await api(cfg.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    formDirty=false;
    closeModal(true);
    toast(`${r.action||cfg.label} started · backup ${r.backup_name||'created'}`);
    if(r.restarting){const c=document.getElementById('content');if(c)c.innerHTML=`<div class="card"><h2>Test environment restarting…</h2><p class="muted">${esc(r.message||'The service is applying the reset. The persistent disk and pre-reset backups remain attached.')}</p><p>Automatic pre-reset backup: <b>${esc(r.backup_name||'')}</b></p><p class="muted">This page will reload shortly. A Full Reset may require you to sign in again.</p></div>`;setTimeout(()=>{formDirty=false;location.reload()},7000)}else await v319RenderSettingsPanel();
    return true;
  }catch(x){if(btn)btn.disabled=false;toast(x.message);return false}finally{window.__v3252ResetBusy=false}
};
window.v319CreateBackup=async function(){const reason=await reasonAction({title:'Create Database Backup',message:'A point-in-time local database copy will be created and logged.',confirmLabel:'Create Backup'});if(reason===null)return;try{const r=await api('/api/system-settings-v319/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast(`${r.backup_name} created · ${fileSizeV319(r.size_bytes)}`);await v319RenderSettingsPanel()}catch(x){toast(x.message)}};

async function v319RenderAudit(panel,row,meta){const rows=await api('/api/system-settings-v319/system-audit').catch(()=>[]);panel.innerHTML=`<section class="card"><div class="section-title"><div><h2>System Audit</h2><div class="muted">Immutable administrative history for settings, SMTP, password resets, bank configuration, migrations, backups and AI settings.</div></div><span class="pill blue">${rows.length} recent event(s)</span></div><div class="table-wrap"><table class="table"><tr><th>Date</th><th>User</th><th>Entity</th><th>Action</th><th>Details</th></tr>${rows.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.user_name||'System')}</td><td>${esc(a.entity)}</td><td>${esc(a.action)}</td><td><small>${esc(a.details||'')}</small></td></tr>`).join('')||'<tr><td colspan="5">No administrative audit records.</td></tr>'}</table></div></section>`;translateElement(panel)}

async function v319RenderAi(panel,row,meta){const st=v319ScopeState(),status=await api('/api/system-settings-v319/ai/status'),extra=`<div class="card" style="margin-top:12px"><h3>AI Provider Credential</h3><div class="grid g2"><div class="field"><label>API Key / Credential</label><input name="secret_api_key" type="password" autocomplete="new-password" placeholder="${row.api_key_set?'Stored securely — enter only to replace':'Enter provider API key'}"></div><label class="order-row"><span>Credential status</span><b>${row.api_key_set?'Stored securely':'Not configured'}</b></label></div><label><input type="checkbox" name="clear_api_key" value="1"> Clear stored AI credential</label><small class="muted">Credentials are never shown again in plain text.</small></div>`;panel.innerHTML=v319GenericFormHtml(st,row,meta,{extra})+`<section class="card" style="margin-top:12px"><div class="section-title"><div><h3>AI Assistant Safety & Diagnostics</h3><div class="muted">${esc(status.diagnostic||'')}</div></div><button class="btn primary" onclick="v319AiDiagnostic()">Test Assistant Configuration</button></div><div class="grid g3"><div class="card stat"><small>Enabled</small><b>${status.enabled?'Yes':'No'}</b></div><div class="card stat"><small>Provider / Model</small><b>${esc(status.provider||'—')} · ${esc(status.default_model||'—')}</b></div><div class="card stat"><small>Credential</small><b>${status.api_key_set?'Stored':'Missing'}</b></div></div><div class="workspace-banner" style="margin-top:12px"><b>Mandatory authorization chain</b><span>${esc(status.authorization_chain||'User → Business Unit → Module → Record → Sensitive Permission')}</span></div><div class="v319-evidence-note" style="margin-top:10px"><b>Consequential actions:</b> AI may prepare an action, but Review & Confirm → user confirmation → commit → audit remains mandatory. Direct unrestricted database access is not permitted.</div><div id="v319AiDiagnosticResult"></div></section>`;translateElement(panel)}
window.v319AiDiagnostic=async function(){try{const r=await api('/api/system-settings-v319/ai/diagnostic',{method:'POST'}),el=document.getElementById('v319AiDiagnosticResult');if(el)el.innerHTML=`<div class="workspace-banner" style="margin-top:12px"><b>${r.ok?'Configuration ready':'Configuration incomplete'}</b><span>${esc((r.checks||[]).map(x=>x.key+': '+(x.ok?'OK':'Missing')).join(' · '))}</span></div>`;toast(r.ok?'AI configuration checks passed':'AI configuration needs attention')}catch(x){toast(x.message)}};

// Persist selected language immediately in UI + account. Local storage remains a safe offline fallback.
try{setLanguage=function(lang){lang=lang==='en'?'en':'ko';currentLanguage=lang;document.documentElement.lang=lang;localStorage.setItem('bo_language',lang);if(me){me.preferred_language=lang;localStorage.removeItem('bo_prelogin_language');api('/api/me/language',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({preferred_language:lang})}).catch(e=>toast('Language saved locally; account sync failed: '+e.message))}else localStorage.setItem('bo_prelogin_language',lang);if(document.getElementById('confirmRoot'))document.getElementById('confirmRoot').innerHTML='';if(me)render();else login()}}catch(_){ }

// Fix supplier screen modal lifecycle: refresh the existing Supplier page instead of opening a duplicate list modal.
try{const baseSupplier=excavatorSuppliers;excavatorSuppliers=async function(c){if(!c&&view==='excavatorSuppliers'){try{closeModal(true)}catch(_){}c=document.getElementById('content')}return baseSupplier(c)}}catch(_){ }

function fileSizeV319(n){n=Number(n||0);if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(2)+' MB'}
function v319Overlay(html){document.getElementById('v319Overlay')?.remove();const d=document.createElement('div');d.id='v319Overlay';d.className='v319-preview-layer';d.innerHTML=`<div class="v319-preview-card">${html}</div>`;document.body.appendChild(d);translateElement(d);return d}
window.closeV319Overlay=function(){document.getElementById('v319Overlay')?.remove()};
window.previewAttachmentV319=function(url,name='Attachment',mime=''){const safe=esc(url),isImg=/^image\//i.test(mime)||/\.(png|jpe?g|webp|gif|bmp)$/i.test(name),isPdf=/pdf/i.test(mime)||/\.pdf$/i.test(name);v319Overlay(`<div class="section-title"><div><h2>File Preview</h2><div class="muted" data-no-i18n>${esc(name)}</div></div><button class="btn" onclick="closeV319Overlay()">✕</button></div>${isImg?`<div class="v319-preview-pane"><img src="${safe}" alt="${esc(name)}"></div>`:isPdf?`<div class="v319-preview-pane"><iframe src="${safe}" title="${esc(name)}" style="height:65vh"></iframe></div>`:`<div class="card"><b>Preview is not available for this file type.</b><p class="muted">The original file format is preserved. Use Download Original to open it in a compatible application.</p></div>`}<div class="actions"><button class="btn" onclick="closeV319Overlay()">Close</button><a class="btn primary" href="${safe}" download>Download Original</a></div>`)};
// V30.20 removes upload-time attachment optimization/review entirely. Stored-file preview/download remains below.

// Excavator document workflow: preview first, preserve format, authorized soft-delete/archive and full history.
try{excavatorDocuments=async function(id){const [docs,hist]=await Promise.all([api('/api/excavator/assets/'+id+'/documents'),api('/api/excavator/assets/'+id+'/documents-history-v319')]),archived=hist.filter(x=>Number(x.archived||0));const canDelete=me.role==='CEO / Owner'||canDo('documents','delete')||canDo('excavator','delete');modal(`<h2>Documents</h2><p class="muted">Select valid file(s) and upload directly. Original formats are preserved; authorized delete archives the record and retains recoverable history.</p><form data-bom-no-review="1" onsubmit="uploadExcavatorDocuments(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Stage</label><select name="stage">${['Purchase','Costs','Repair','Parts','Local Sale','Export Preparation','Export/Shipping','Payment','General'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Files</label><input name="files" type="file" multiple required></div></div><div class="actions"><button class="btn primary">Upload Documents</button></div></form><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Stage</th><th>Original File</th><th>Date</th><th>Actions</th></tr>${docs.map(d=>`<tr><td>${esc(d.stage)}</td><td data-no-i18n>${esc(d.original_name)}</td><td>${esc(d.created_at)}</td><td><div class="v319-doc-actions"><button class="btn small primary" onclick='previewAttachmentV319(${JSON.stringify(d.file_path)},${JSON.stringify(d.original_name)},${JSON.stringify(d.mime_type||'')})'>Preview</button>${canDelete?`<button class="btn small danger" onclick="deleteExcavatorDocumentV319(${id},${d.id})">Delete / Archive</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="4">No documents yet.</td></tr>'}</table></div>${archived.length?`<details style="margin-top:14px"><summary><b>Archived Documents (${archived.length})</b></summary><div class="table-wrap"><table class="table"><tr><th>File</th><th>Archived</th><th>Reason</th><th>History</th></tr>${archived.map(d=>`<tr class="v319-archived-row"><td>${esc(d.original_name)}</td><td>${esc(d.archived_at||'')}</td><td>${esc(d.archive_reason||'')}</td><td><button class="btn small" onclick='previewAttachmentV319(${JSON.stringify(d.file_path)},${JSON.stringify(d.original_name)},${JSON.stringify(d.mime_type||'')})'>Preview Preserved Original</button></td></tr>`).join('')}</table></div></details>`:''}`,'wide')};}catch(_){ }
window.deleteExcavatorDocumentV319=async function(assetId,docId){const reason=await reasonAction({title:'Delete / Archive Document',message:'The document will disappear from the active list, but its original file and complete audit history will be preserved.',confirmLabel:'Archive Document',tone:'danger',placeholder:'Reason for removing this document from the active record'});if(reason===null)return;try{await api(`/api/excavator/assets/${assetId}/documents/${docId}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast('Document archived; original preserved');excavatorDocuments(assetId)}catch(e){toast(e.message)}};

// Operational payment accounts are resolved from System Settings and respect BU/user scope.
window.v319PaymentAccounts=async function(bu){try{return (await api('/api/system-settings-v319/bank-accounts'+(bu?'?business_unit_id='+encodeURIComponent(bu):''))).filter(x=>Number(x.active||0)===1&&String(x.status||'Active')==='Active'&&!/^\s*Unassigned KRW Bank\s*$/i.test(String(x.name||'')))}catch(_){return []}};
window.v319PaymentAccountOptions=function(rows,selected){return `<option value="">Select configured account</option>`+(rows||[]).map(a=>`<option value="${a.id}" ${String(a.id)===String(selected||'')?'selected':''}>${esc(a.name)} · ${esc(a.bank_name||a.payment_type||'')} · ${esc(a.currency||'KRW')} · ${esc(a.account_number_masked||'')}</option>`).join('')};
window.v319SetAccountRequirement=function(f,methodName='payment_method'){if(!f)return;const method=f.elements?.[methodName],account=f.elements?.payment_account_id,ref=f.elements?.payment_reference||f.elements?.reference,nonCash=String(method?.value||'').toLowerCase()!=='cash';if(account)account.required=nonCash;if(ref){ref.required=nonCash;ref.placeholder=nonCash?'Required for non-cash':'Optional for cash'}};

// Machine costs: multi-currency, mandatory payment method, conditional reference, evidence, edit and controlled delete.
window.excavatorCostMetaV319=function(x){try{return typeof x.metadata==='string'?JSON.parse(x.metadata||'{}'):(x.metadata||{})}catch(_){return {}}};
window.excavatorCostRowV319=function(x,assetId){const m=excavatorCostMetaV319(x),orig=m.original_amount??x.amount,curr=m.original_currency||x.currency||'KRW',fx=m.fx_rate_to_krw||1,method=m.payment_method||'—',ref=m.payment_reference||'—',voided=['Cancelled','Voided'].includes(x.status);return `<div class="row ${voided?'v331-voided-row':''}"><span>${esc(x.type)}<small class="v319-cost-meta">${esc(x.transaction_date||'')} · ${money(orig)} ${esc(curr)}${curr!=='KRW'?' · FX '+esc(fx):''} · ${esc(method)} · Ref ${esc(ref)}</small>${voided&&x.void_reason?`<small class="v319-cost-meta">Void reason: ${esc(x.void_reason)}</small>`:''}</span><span class="v319-cost-actions"><b>₩ ${money(x.amount)}</b>${voided?'<span class="pill bad">Voided</span>':`<button class="btn small" onclick="excavatorAddCost(${assetId},${x.id})">Edit</button><button class="btn small danger" onclick="deleteExcavatorCostV319(${assetId},${x.id})">Void</button>`}</span></div>`};
try{excavatorAddCost=async function(id,txid=0){let x=null,m={};if(txid){const rows=await api('/api/excavator/assets/'+id+'/transactions');x=rows.find(r=>Number(r.id)===Number(txid));if(!x)return toast('Cost record not found');m=excavatorCostMetaV319(x)}const bu=selectedUnitId||me.business_unit_id||'',accounts=await v319PaymentAccounts(bu),curr=m.original_currency||x?.currency||'KRW',amt=m.original_amount??x?.amount??'',fx=m.fx_rate_to_krw??1,method=m.payment_method||'Bank',ref=m.payment_reference||'',paymentAccount=m.payment_account_id||'';modal(`<h2>${txid?'Edit':'Add'} Machine Cost</h2><p class="muted">Payment Method is mandatory. Non-cash payments must use an active Company Bank / Payment Account configured in System Settings and include a reference. Existing evidence remains preserved when a cost is edited.</p><form data-account-country="South Korea" data-account-direction="payment" onsubmit="saveExcavatorCostV319(event,${id},${txid})" enctype="multipart/form-data"><div class="grid g3"><div class="field"><label>Cost Type *</label><select name="type" required>${['Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost'].map(v=>`<option ${x?.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Payment Amount *</label><input name="payment_amount" type="number" min="0.01" step="0.01" value="${esc(amt)}" oninput="v319CostCalc(this.form)" required></div><div class="field"><label>Payment Currency *</label><select name="payment_currency" onchange="v319CostCalc(this.form)" required>${['KRW','USD','PKR','EUR','JPY','CNY'].map(v=>`<option ${curr===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="grid g3"><div class="field"><label>FX Rate to KRW *</label><input name="fx_rate_to_krw" type="number" min="0.000001" step="0.000001" value="${esc(fx)}" oninput="v319CostCalc(this.form)" required></div><div class="field"><label>Accounting Amount (KRW)</label><input name="krw_preview" disabled></div><div class="field"><label>Date *</label><input name="transaction_date" type="date" value="${esc(String(x?.transaction_date||'').slice(0,10))}" required></div></div><div class="grid g3"><div class="field"><label>Mode of Payment *</label><select name="payment_method" onchange="v319CostMethod(this.form)" required>${['Bank','Cash','Card','Cheque','Other'].map(v=>`<option ${method===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Company Bank / Payment Account</label><select name="payment_account_id">${v319PaymentAccountOptions(accounts,paymentAccount)}</select><small class="muted">Filtered by current BU and your permission.</small></div><div class="field"><label>Payment Reference</label><input name="payment_reference" value="${esc(ref)}" placeholder="Required for non-cash"></div></div><div class="grid g2"><div class="field"><label>Include in Machine Cost?</label><select name="include_in_machine_cost"><option value="1" ${m.include_in_machine_cost===false?'':'selected'}>Yes</option><option value="0" ${m.include_in_machine_cost===false?'selected':''}>No — Business Expense</option></select></div><div class="field"><label>Supplier / Payee</label><input name="counterparty" value="${esc(x?.counterparty||'')}"></div></div><div class="field"><label>Description</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="field"><label>Receipt / Evidence ${txid?'(new file optional; existing evidence is preserved)':'*'}</label><input name="files" type="file" multiple ${txid?'':'required'} accept="application/pdf,image/*"></div><input type="hidden" name="stage" value="Costs"><input type="hidden" name="status" value="Open"><div class="actions"><button type="button" class="btn" onclick="excavatorOpenMachine(${id})">Cancel</button><button class="btn primary">${txid?'Update':'Save'} Cost</button></div></form>`);const form=document.querySelector('#modalRoot form');v319CostCalc(form);v319CostMethod(form)}}catch(_){ }
window.v319CostCalc=function(f){if(!f)return;const cur=f.payment_currency.value,amt=Number(f.payment_amount.value||0);if(cur==='KRW'){f.fx_rate_to_krw.value=1;f.fx_rate_to_krw.readOnly=true}else f.fx_rate_to_krw.readOnly=false;f.krw_preview.value='₩ '+money(amt*Number(f.fx_rate_to_krw.value||0))};
window.v319CostMethod=function(f){v319SetAccountRequirement(f,'payment_method')};
window.saveExcavatorCostV319=async function(e,id,txid){e.preventDefault();const f=e.target;v319CostMethod(f);if(!f.reportValidity())return;const fd=new FormData(f);try{await multipartApi(`/api/excavator/assets/${id}/transactions${txid?'/'+txid:''}`,fd,{method:txid?'PUT':'POST'});closeModal(true);toast(txid?'Machine cost updated':'Machine cost added');excavatorOpenMachine(id)}catch(x){toast(x.message)}};
window.deleteExcavatorCostV319=async function(id,txid){const reason=await reasonAction({title:'Request Machine Cost Void',message:'The original machine cost, evidence and audit history will be retained. The system will show and update linked Finance/Accounting impact.',confirmLabel:'Review Void Impact',tone:'danger'});if(reason===null)return;try{const r=await api(`/api/excavator/assets/${id}/transactions/${txid}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});if(r.approval_required)toast(r.message||'Cost reversal submitted for approval');else toast('Machine cost reversed');excavatorOpenMachine(id)}catch(x){toast(x.message)}};

// Machine payment form: method required, reference only for non-cash, evidence mandatory.
try{excavatorPaymentForm=async function(id){const bu=selectedUnitId||me.business_unit_id||'',accounts=await v319PaymentAccounts(bu);modal(`<h2>Add Payment</h2><p class="muted">Non-cash payments require a configured Company Bank / Payment Account and payment reference. Evidence is mandatory.</p><form data-account-country="South Korea" data-account-currency="KRW" data-account-direction="payment" onsubmit="saveExcavatorPayment(event,${id})" enctype="multipart/form-data"><div class="grid g3"><div class="field"><label>Payment For</label><select name="payment_type"><option>Purchase</option></select></div><div class="field"><label>Amount (KRW) *</label><input name="amount" type="number" min="0.01" step="1" required></div><div class="field"><label>Payment Date *</label><input name="payment_date" type="date" required></div></div><div class="grid g3"><div class="field"><label>Mode of Payment *</label><select name="method" onchange="v319MachinePaymentMethod(this.form)" required><option>Bank</option><option>Cash</option><option>Card</option><option>Cheque</option><option>Other</option></select></div><div class="field"><label>Company Bank / Payment Account</label><select name="payment_account_id">${v319PaymentAccountOptions(accounts,'')}</select></div><div class="field"><label>Payment Reference</label><input name="reference" required placeholder="Required for non-cash"></div></div><div class="field"><label>Payment Receipt / Evidence *</label><input name="receipt" type="file" multiple required accept="application/pdf,image/*"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Payment</button></div></form>`);v319MachinePaymentMethod(document.querySelector('#modalRoot form'))}}catch(_){ }
window.v319MachinePaymentMethod=function(f){v319SetAccountRequirement(f,'method')};

// Finance table/state behavior and evidence preview.
try{financeRowHtml=function(x){const amount=financeAmount(x),status=financeStatusLabel(x),source=(x.source_label||x.source_type||'Manual')+(x.source_id?' #'+x.source_id:''),linked=Number(x.linked_evidence_count||0),has=Number(x.attachment_count||0)>0||!!x.receipt_file||linked>0,bulk=financeCanVerify()&&['Pending Verification','Resubmitted'].includes(status)&&amount<=5000000&&has&&x.status!=='Voided',label=(status==='Verified'||status==='Voided'||x.status==='Voided')?'View':'Open Verification';return `<tr data-finance-id="${x.id}" data-status="${esc(status)}" data-type="${esc(x.type||'')}" data-evidence="${has?'yes':'no'}" data-request="${Number(x.open_request_count||0)>0?'yes':'no'}" data-text="${esc((source+' '+(x.reference||'')+' '+(x.category||'')+' '+(x.description||'')+' '+(x.business_unit||'')).toLowerCase())}">${financeCanVerify()?`<td class="check-col">${bulk?`<input class="finance-bulk" type="checkbox" value="${x.id}">`:''}</td>`:''}<td>${esc(x.transaction_date||x.created_at||'')}</td><td>${esc(x.business_unit||'')}</td><td><button class="link-btn" onclick="financeOpen(${x.id})"><b>${esc(source)}</b></button><div class="muted">${esc(x.description||'')}</div></td><td><b>${esc(x.type||'')}</b><div class="muted">${esc(x.category||'')}</div></td><td><b>₩ ${money(amount)}</b>${x.original_currency&&x.original_currency!=='KRW'?`<div class="muted">${money(x.original_amount)} ${esc(x.original_currency)} @ ${esc(x.fx_rate||1)}</div>`:''}</td><td>${esc(x.reference||'—')}</td><td>${has?`<span class="pill good">Evidence ${Number(x.attachment_count||0)+(x.receipt_file?1:0)+linked}</span>`:'<span class="pill warn">⚠ Missing Evidence</span>'}</td><td><span class="pill ${financeStatusClass(status)}">${esc(t(status))}</span></td><td><button class="btn small ${label==='View'?'':'primary'}" onclick="financeOpen(${x.id})">${label}</button></td></tr>`}}catch(_){ }
try{financeOpen=async function(id){try{const d=await api('/api/finance/'+id+'/detail'),x=d.finance,status=financeStatusLabel(x),voided=x.status==='Voided'||status==='Voided',verified=status==='Verified',correction=status==='Correction Required',pending=['Pending Verification','Resubmitted'].includes(status),canVerify=financeCanVerify();const ev=[];if(x.receipt_file)ev.push({name:'Receipt / Evidence',path:x.receipt_file.startsWith('/')?x.receipt_file:'/uploads/'+x.receipt_file,mime:''});for(const a of d.attachments||[])ev.push({name:a.title||a.original_name||'Evidence',path:a.file_path,mime:a.mime_type||''});for(const a of d.linked_evidence||[])if(a.file_path)ev.push({name:a.evidence_label||'Linked Evidence',path:a.file_path,mime:a.mime_type||''});const buttons=[];if(pending&&canVerify){buttons.push(`<button class="btn primary" onclick="financeDecision(${id},'verify')">Verify Payment</button>`,`<button class="btn" onclick="financeDecision(${id},'correction')">Request Correction</button>`,`<button class="btn danger" onclick="voidFinance(${id})">Request Void</button>`)}else if(correction&&d.can_correct)buttons.push(`<button class="btn primary" onclick="financeEdit(${id})">Correct & Resubmit</button>`);else if(verified)buttons.push(`<button class="btn" onclick="financeRequestChange(${id})">Request Controlled Change</button>`);const warnings=(d.warnings||[]).map(w=>`<div class="review-warning ${w.level==='critical'?'critical':''}"><b>${w.level==='critical'?'⛔':'⚠'} ${esc(String(w.code||'').replaceAll('_',' '))}</b><span>${esc(w.message)}</span></div>`).join('');openWorkflowHtmlV324(`<div class="finance-review-header"><div><button class="btn small" onclick="closeWorkflowPageV324(true)">← Back to Finance</button><h2>${verified||voided?'Finance Record':'Finance Verification'} #${x.id}</h2><div class="muted">${esc(x.business_unit||'')} · <span class="pill ${financeStatusClass(status)}">${esc(t(status))}</span></div></div><button class="btn" onclick="closeModal()">✕</button></div>${warnings?`<div class="review-warnings">${warnings}</div>`:''}<div class="finance-review-grid"><section class="card"><h3>Financial Record</h3><div class="detail-list"><div><small>Type / Category</small><b>${esc(x.type)} · ${esc(x.category)}</b></div><div><small>Accounting Amount</small><b>₩ ${money(financeAmount(x))}</b></div><div><small>Payment Currency</small><span>${money(x.original_amount||x.amount)} ${esc(x.original_currency||'KRW')} · FX ${esc(x.fx_rate||1)}</span></div><div><small>Date / Method</small><span>${esc(x.transaction_date||x.created_at||'')} · ${esc(x.payment_method||'—')}</span></div><div><small>Payment Reference</small><span>${esc(x.reference||'—')}</span></div><div><small>Entered by</small><span>${esc(x.created_by_name||'System')} · ${esc(x.created_at||'')}</span></div></div></section><section class="card"><h3>Source & Evidence</h3><div class="detail-list"><div><small>Source</small><b>${esc(d.source?.label||x.source_type||'Manual')} ${x.source_id?'#'+x.source_id:''}</b></div><div><small>Linked Record</small><span>${esc(d.source?.record||'Manual finance entry')}</span></div><div><small>Source Status</small><span>${esc(d.source?.status||'—')}</span></div></div><div class="evidence-list">${ev.map(a=>`<button class="btn small" onclick='previewAttachmentV319(${JSON.stringify(a.path)},${JSON.stringify(a.name)},${JSON.stringify(a.mime)})'>Preview · ${esc(a.name)}</button>`).join('')||'<span class="pill warn">⚠ Missing Evidence</span>'}</div>${d.source?.action_view?`<button class="btn small primary" onclick="closeModal(true);notificationNavigate('${esc(d.source.action_view)}',${Number(d.source.action_id||0)})">Open Source Record</button>`:''}</section></div><section class="card finance-control-card"><div class="section-title"><div><h3>Verification & Control</h3><div class="muted">Actions are state-driven. Verified and voided records are read-only; corrections/reversals preserve history.</div></div><span class="pill ${financeStatusClass(status)}">${esc(t(status))}</span></div>${x.verification_note?`<div class="review-note"><b>Latest review note</b><span>${esc(x.verification_note)}</span></div>`:''}<div class="actions finance-actions">${buttons.join('')}<button class="btn" onclick="financeCorrectionHistoryV319(${id})">View Full History</button></div></section><section class="card"><h3>Transaction Timeline</h3>${(d.timeline||[]).map(z=>`<div class="timeline-item"><div><b>${esc(z.action)}</b><div class="muted">${esc(z.details||'')}</div></div><time>${esc(z.created_at||'')}</time></div>`).join('')||'<div class="empty">No timeline events.</div>'}</section>`,'wide finance-review-modal')}catch(e){toast(e.message)}}}catch(_){ }
window.financeCorrectionHistoryV319=async function(id){try{const d=await api('/api/finance/'+id+'/detail');if(d.correction)return financeCorrectionOpen(d.correction.id);toast('The full transaction timeline is shown on this Finance record.')}catch(e){toast(e.message)}};
try{voidFinance=async function(id){const d=await api('/api/finance/'+id+'/detail'),f=d.finance,reason=await reasonAction({title:'Request Finance Void',message:'The Finance record remains in audit history. Financial effect is removed only through the controlled void workflow.',confirmLabel:'Request Void',tone:'danger',details:[{label:'Finance Record',value:'#'+id},{label:'Amount',value:'₩ '+money(f.krw_amount||f.amount)}]});if(reason===null)return;try{const r=await api('/api/finance/'+id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:reason.trim()})});closeModal(true);toast(r.approval_required?(r.message||'Finance void submitted for approval'):'Finance entry voided');await refreshCurrentView({preserve:true})}catch(x){toast(x.message)}}}catch(_){ }

// Finance correction: show previous evidence, permit active-evidence removal while retaining immutable history.
try{financeCorrectionRespond=async function(id){try{await api('/api/finance/corrections/'+id+'/view',{method:'POST'});const d=await api('/api/finance/corrections/'+id);if(!d.can_correct)return toast('Only the original record creator can correct and resubmit this transaction.');const fields=(d.form?.fields||[]).map(field=>correctionFieldHtml(field,d.form.record)).join(''),atts=d.attachments||[];modal(`<div class="section-title"><div><h2>Correct & Resubmit Finance Entry</h2><div class="muted">${esc(t(d.form?.title||d.finance.source_type||'Financial Record'))} · Finance #${d.finance.id}</div></div><span class="pill warn">${esc(t(d.correction.status))}</span></div><div class="review-warning critical"><b>Correction requested</b><span>${esc(d.correction.reason)} · ${esc(d.correction.requested_changes||'')}</span></div><form onsubmit="saveFinanceCorrection(event,${id},${d.finance.id})" enctype="multipart/form-data"><div class="correction-form-grid">${fields}</div><section class="card"><h3>Current / Previous Evidence</h3>${d.finance.receipt_file?`<label class="order-row"><span><button type="button" class="btn small" onclick='previewAttachmentV319(${JSON.stringify(d.finance.receipt_file.startsWith('/')?d.finance.receipt_file:'/uploads/'+d.finance.receipt_file)},"Finance receipt","")'>Preview Current Receipt</button><small class="muted">Original will remain archived if removed from the active corrected record.</small></span><span><input type="checkbox" name="remove_receipt_file" value="1"> Remove from active</span></label>`:''}${atts.map(a=>`<label class="order-row ${Number(a.archived||0)?'v319-archived-row':''}"><span><button type="button" class="btn small" onclick='previewAttachmentV319(${JSON.stringify(a.file_path)},${JSON.stringify(a.original_name||a.title||'Evidence')},${JSON.stringify(a.mime_type||'')})'>Preview · ${esc(a.original_name||a.title||'Evidence')}</button><small class="muted">${Number(a.archived||0)?'Archived history · '+esc(a.archive_reason||''):'Active evidence'}</small></span>${Number(a.archived||0)?'<span class="pill blue">Preserved Original</span>':`<span><input type="checkbox" name="remove_attachment_ids" value="${a.id}"> Remove from active</span>`}</label>`).join('')||'<div class="muted">No standalone Finance attachments.</div>'}</section><div class="field"><label>Correction Response *</label><textarea name="response_note" required>${esc(d.correction.response_note||'')}</textarea></div><div class="field"><label>New / Revised Evidence${d.has_evidence?'':' *'}</label><input name="attachments" type="file" multiple accept="application/pdf,image/*" ${d.has_evidence?'':'required'}><small class="muted">Old files are never physically erased; replaced evidence remains in correction history.</small></div><div class="actions"><button type="button" class="btn" onclick="financeCorrectionOpen(${id})">Cancel</button><button class="btn primary">Save & Resubmit</button></div></form>`,'wide')}catch(e){toast(e.message)}}}catch(_){ }

// Manual Finance entry consumes the same configured payment-account source of truth.
try{financeForm=async function(){const u=await api('/api/business-units'),def=selectedUnitId||me.business_unit_id||u[0]?.id||'',accounts=await v319PaymentAccounts(def);openWorkflowHtmlV324(`<div class="section-title"><div><h2>Manual Finance Entry</h2><div class="muted">Manual entries are source-tagged and submitted for Finance verification. Bank/payment accounts come from System Settings.</div></div><button class="btn" onclick="closeModal()">✕</button></div><form onsubmit="saveFinance(event)" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Business Unit *</label><select name="business_unit_id" required onchange="v319FinanceAccountRefresh(this.form)">${u.map(x=>`<option value="${x.id}" ${String(x.id)===String(def)?'selected':''} data-no-i18n>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Type *</label><select name="type"><option>Expense</option><option>Revenue</option></select></div></div><div class="grid g2"><div class="field"><label>Category *</label><select name="category"><option>General Expense</option><option>Salary / Wages</option><option>Rent</option><option>Utilities</option><option>Transport</option><option>Bank Charges</option><option>Other Expense</option><option>Other Income</option></select></div><div class="field"><label>Transaction Date *</label><input name="transaction_date" type="date" required></div></div><div class="grid g3"><div class="field"><label>Payment Amount *</label><input name="original_amount" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Payment Currency *</label><select name="original_currency"><option>KRW</option><option>USD</option><option>PKR</option><option>EUR</option><option>JPY</option><option>CNY</option></select></div><div class="field"><label>FX Rate to KRW *</label><input name="fx_rate" type="number" step="0.000001" min="0.000001" value="1" required></div></div><div class="grid g3"><div class="field"><label>Payment Method *</label><select name="payment_method" required onchange="v319FinanceMethod(this.form)"><option>Bank</option><option>Cash</option><option>Card</option><option>Cheque</option><option>Other</option></select></div><div class="field"><label>Company Bank / Payment Account</label><select name="payment_account_id">${v319PaymentAccountOptions(accounts,'')}</select></div><div class="field"><label>Payment Reference</label><input name="reference" required placeholder="Required for non-cash"></div></div><div class="grid g2"><div class="field"><label>Due date</label><input name="due_date" type="date"></div><div class="field"><label>Receipt / Evidence</label><input name="attachments" type="file" multiple></div></div><div class="field"><label>Description *</label><textarea name="description" required></textarea></div><input type="hidden" name="source_type" value="Manual"><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Review & Submit</button></div></form>`,'wide');v319FinanceMethod(workflowSurfaceV324().querySelector('form'))}}catch(_){ }
window.v319FinanceAccountRefresh=async function(f){if(!f)return;const rows=await v319PaymentAccounts(f.business_unit_id.value),sel=f.payment_account_id;sel.innerHTML=v319PaymentAccountOptions(rows,'');v319FinanceMethod(f)};
