function v320TargetOptions(type,id,users){
  if(type==='business_unit')return (unitOptions||[]).map(x=>`<option value="${x.id}" ${Number(id)===Number(x.id)?'selected':''}>${esc(x.name)}</option>`).join('');
  if(type==='user')return (users||[]).map(x=>`<option value="${x.id}" ${Number(id)===Number(x.id)?'selected':''}>${esc(x.name)} · ${esc(t(x.role))}</option>`).join('');
  return '<option value="0">Blue Ocean Market</option>';
}
async function systemSettingsV320(c){
  if(!(me?.role==='CEO / Owner'||hasSensitive('sensitive.system_admin')))throw new Error('System Settings requires CEO / Owner or authorized System Administrator access.');
  const catalog=await api('/api/system-settings-v319/catalog');window._v319Catalog=catalog;
  let users=[];try{users=await api('/api/users')}catch(_){ }
  const st=window._v319Scope||{type:'company',id:0,section:'overview'};
  if(!catalog.sections.some(x=>x.key===st.section))st.section='overview';
  if(st.type==='business_unit'&&!Number(st.id))st.id=Number(selectedUnitId||unitOptions?.[0]?.id||0);
  if(st.type==='user'&&!Number(st.id))st.id=Number(users?.[0]?.id||me.id);
  window._v319Scope=st;
  let navHtml='',last='';for(const s of catalog.sections){const group=sectionGroups[s.key]||'Other';if(group!==last){navHtml+=`<div class="v320-nav-group">${esc(group)}</div>`;last=group}navHtml+=`<button class="btn ${s.key===st.section?'active':''}" data-v320-section="${s.key}" onclick="v319SettingsSection('${s.key}')"><span>${sectionIcons[s.key]||'⚙️'}</span><span>${esc(t(sectionLabel(s)))}</span><span class="v320-type ${s.policy==='policy'?'policy':''}">${s.policy==='policy'?'Policy':'Technical'}</span></button>`}
  const selectedBu=(unitOptions||[]).find(x=>String(x.id)===String(selectedUnitId));
  c.innerHTML=`<div class="v320-settings"><div class="v320-hero"><div><h1>${esc(t('System Settings'))}</h1><p>Manage company policy and technical configuration in one clear place. Settings follow Company Default → Business Unit Override → User Override and every high-risk change remains auditable.</p></div><span class="pill blue">V30.20</span></div><div class="v320-scope"><div class="field"><label>Configuration Scope</label><select id="v319ScopeType" onchange="v319ChangeScope(this.value)"><option value="company" ${st.type==='company'?'selected':''}>Company Default</option><option value="business_unit" ${st.type==='business_unit'?'selected':''}>BU Override</option><option value="user" ${st.type==='user'?'selected':''}>User Override</option></select></div><div class="field"><label>Target</label><select id="v319ScopeId" onchange="v319ChangeScopeId(this.value)" ${st.type==='company'?'disabled':''}>${v320TargetOptions(st.type,st.id,users)}</select></div><div class="field"><label>Current Workspace</label><input value="${esc(selectedBu?.name||'Company / assigned scope')}" disabled></div></div><div class="v320-shell"><aside class="v320-nav v319-settings-nav">${navHtml}</aside><main id="v319SettingsPanel" class="v320-panel"></main></div></div>`;
  translateElement(c);await window.v319SettingsSection(st.section);
}

const previousLoadView=loadView;
loadView=async function(){if(view==='systemSettings'){const c=document.getElementById('content');c.innerHTML='<div class="card">Loading System Settings…</div>';try{return await systemSettingsV320(c)}catch(e){c.innerHTML=`<div class="card"><b>System Settings could not load</b><p class="muted">${esc(e.message)}</p></div>`;return}}return previousLoadView()};
window.v319ChangeScope=async function(type){const st=window._v319Scope||{section:'overview'};st.type=type;st.id=type==='company'?0:Number(type==='business_unit'?(selectedUnitId||unitOptions?.[0]?.id||0):me.id);window._v319Scope=st;return loadView()};
window.v319ChangeScopeId=async function(id){const st=window._v319Scope||{};st.id=Number(id||0);window._v319Scope=st;return window.v319SettingsSection(st.section||'overview')};
window.v319SettingsSection=async function(section){const st=window._v319Scope||{type:'company',id:0};st.section=section;window._v319Scope=st;document.querySelectorAll('.v320-nav .btn').forEach(b=>b.classList.toggle('active',b.dataset.v320Section===section));if(section==='bank_accounts')return renderFinancialAccountsV320();if(section==='files_attachments')return renderAttachmentSettingsV320();return v319SectionOriginal(section)};

function v320ScopeQuery(){const st=window._v319Scope||{type:'company',id:0};const q=new URLSearchParams({scope_type:st.type,scope_id:String(st.id||0)});if(selectedUnitId)q.set('business_unit_id',selectedUnitId);if(st.type==='user'&&st.id)q.set('user_id',st.id);return q.toString()}
async function renderAttachmentSettingsV320(){
  const p=document.getElementById('v319SettingsPanel');if(!p)return;const d=await api('/api/system-settings-v319?'+v320ScopeQuery()),row=d.sections.files_attachments||{},v=row.saved||row.effective||{},eff=row.effective||{},can=!!row.can_edit;
  window._v320FileSettingsBase={...eff,...(row.saved||{}),optimize_images:false,preview_before_store:false};const max=Object.prototype.hasOwnProperty.call(v,'max_file_size_mb')?v.max_file_size_mb:eff.max_file_size_mb, count=Object.prototype.hasOwnProperty.call(v,'max_attachments_per_record')?v.max_attachments_per_record:eff.max_attachments_per_record, types=Object.prototype.hasOwnProperty.call(v,'allowed_file_types')?v.allowed_file_types:eff.allowed_file_types;
  p.innerHTML=`<section class="card"><div class="section-title"><div><h2>File & Attachment Settings</h2><div class="muted">Simple upload rules only. V30.20 removes upload-time compression, optimization, readability confirmation and preview-before-store.</div></div><span class="pill blue">Technical</span></div><div class="v320-friendly-note">Users will see these limits beside attachment fields and valid files upload directly. Existing stored files can still be opened or downloaded normally.</div><form onsubmit="saveAttachmentSettingsV320(event)"><div class="v320-file-policy"><div class="v320-policy-card"><small>Maximum file size</small><b><input name="max_file_size_mb" type="number" min="1" max="500" step="1" value="${esc(max||20)}" ${can?'':'disabled'}> MB</b></div><div class="v320-policy-card"><small>Maximum attachments per upload</small><b><input name="max_attachments_per_record" type="number" min="1" max="100" step="1" value="${esc(count||30)}" ${can?'':'disabled'}></b></div><div class="v320-policy-card"><small>Allowed file formats</small><textarea name="allowed_file_types" rows="3" ${can?'':'disabled'}>${esc(types||'pdf,jpg,jpeg,png,webp,xlsx,xls,csv,doc,docx')}</textarea></div></div>${can?`<div class="field" style="margin-top:14px"><label>Change Reason *</label><textarea name="reason" required placeholder="Why are the attachment limits changing?"></textarea></div><div class="actions"><button type="button" class="btn" onclick="v319SettingsHistory()">Settings History</button><button class="btn primary">Save Attachment Rules</button></div>`:`<div class="muted" style="margin-top:14px">Read only in your current authority.</div>`}</form></section><section class="card" id="v319HistoryPanel" style="display:none;margin-top:12px"></section>`;translateElement(p)
}
window.saveAttachmentSettingsV320=async function(e){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const st=window._v319Scope||{type:'company',id:0},settings={...(window._v320FileSettingsBase||{}),max_file_size_mb:Number(f.max_file_size_mb.value),max_attachments_per_record:Number(f.max_attachments_per_record.value),allowed_file_types:String(f.allowed_file_types.value||'').trim(),optimize_images:false,preview_before_store:false};const reason=String(f.reason?.value||'').trim();const ok=await confirmAction({title:'Save Attachment Rules',message:'These limits will apply to attachment fields across the system. Upload-time compression and preview remain disabled.',confirmLabel:'Save Rules',details:[{label:'Max file size',value:settings.max_file_size_mb+' MB'},{label:'Max attachments',value:settings.max_attachments_per_record},{label:'Formats',value:settings.allowed_file_types}]});if(!ok)return;try{await api('/api/system-settings-v319/files_attachments',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope_type:st.type,scope_id:st.id,reason,settings,confirm_high_risk:true})});window.v319AttachmentSettings=null;v320AttachmentPolicyCache=null;toast('Attachment rules saved');renderAttachmentSettingsV320()}catch(x){toast(x.message)}};

let financialFilterV320='All';
async function renderFinancialAccountsV320(){
  const p=document.getElementById('v319SettingsPanel');if(!p)return;p.innerHTML='<div class="card">Loading financial accounts…</div>';const q=new URLSearchParams();if(selectedUnitId)q.set('business_unit_id',selectedUnitId);const rows=await api('/api/v320/financial-accounts?'+q.toString());const filtered=financialFilterV320==='All'?rows:financialFilterV320==='Archived'?rows.filter(x=>x.status!=='Active'):rows.filter(x=>x.financial_account_type===financialFilterV320&&x.status==='Active');
  p.innerHTML=`<section class="card"><div class="section-title"><div><h2>Company Financial Accounts</h2><div class="muted">Configure multiple bank accounts, cash accounts and company cards. Payment forms show only accounts compatible with the selected payment method.</div></div><span class="pill warn">Policy</span></div><div class="v320-friendly-note"><b>Accounting integration:</b> every active account must map to the correct GL. Closed/archived accounts remain in historical Finance and Accounting records but cannot be used for new transactions.</div><div class="v320-account-toolbar"><div class="v320-account-filters">${['All','Bank','Cash','Card','Archived'].map(x=>`<button class="btn small ${financialFilterV320===x?'primary':''}" onclick="filterFinancialAccountsV320('${x}')">${x}</button>`).join('')}</div><button class="btn primary" onclick="financialAccountFormV320(0)">+ Add Financial Account</button></div><div class="v320-account-grid">${filtered.map(financialCardV320).join('')||'<div class="empty">No financial accounts in this filter.</div>'}</div></section>`;translateElement(p)
}
function financialCardV320(x){const inactive=x.status!=='Active'||Number(x.active||0)!==1,kind=x.financial_account_type||x.payment_type||'Bank';return `<div class="v320-account-card ${inactive?'inactive':''}"><div class="v320-account-head"><div><h3>${esc(x.name)}</h3><div class="v320-account-meta"><span class="pill blue">${esc(kind)}</span><span class="pill ${inactive?'bad':'good'}">${esc(x.status||'Active')}</span>${x.business_unit?`<span class="pill">${esc(x.business_unit)}</span>`:'<span class="pill">Company-wide</span>'}</div></div><b>${esc(x.currency||'KRW')}</b></div><div class="v320-account-detail"><span>Account Country<br><b>${esc(x.account_country||'Country Required')}</b></span><span>Bank / Issuer<br><b>${esc(x.bank_name||x.card_network||'—')}</b></span><span>Account<br><b>${esc(x.account_number_masked||'—')}</b></span><span>GL Mapping<br><b>${esc((x.ledger_code?x.ledger_code+' · ':'')+(x.ledger_name||'Missing'))}</b></span><span>History References<br><b>${Number(x.reference_count||0)}</b></span></div><div class="actions"><button class="btn small" onclick="financialAccountFormV320(${x.id})">Edit</button><button class="btn small" onclick="financialAccountHistoryV320(${x.id})">History</button>${!inactive?`<button class="btn small danger" onclick="closeFinancialAccountV320(${x.id},'${String(x.name).replaceAll("'","&#39;")}','Closed')">Close</button><button class="btn small" onclick="closeFinancialAccountV320(${x.id},'${String(x.name).replaceAll("'","&#39;")}','Archived')">Archive</button>`:''}</div></div>`}
window.filterFinancialAccountsV320=function(x){financialFilterV320=x;renderFinancialAccountsV320()};
window.financialAccountFormV320=async function(id){try{const q=new URLSearchParams();if(selectedUnitId)q.set('business_unit_id',selectedUnitId);const [accounts,ledgers]=await Promise.all([api('/api/v320/financial-accounts?'+q.toString()),api('/api/v320/financial-accounts/ledger-options')]),x=id?accounts.find(a=>Number(a.id)===Number(id)):null,banks=accounts.filter(a=>(a.financial_account_type||a.payment_type)==='Bank'&&a.status==='Active'),type=x?.financial_account_type||'Bank';modal(`<div class="section-title"><div><h2>${id?'Edit':'Add'} Company Financial Account</h2><div class="muted">Create the actual company account used by payments, receipts and Accounting.</div></div><button class="btn" type="button" onclick="closeModal()">✕</button></div><form onsubmit="saveFinancialAccountV320(event,${id||0})"><div class="v320-modal-grid"><div class="field"><label>Account Name / Label *</label><input name="name" required value="${esc(x?.name||'')}"></div><div class="field"><label>Financial Account Type *</label><select name="financial_account_type" required onchange="financialAccountTypeV320(this.form)">${['Bank','Cash','Card','Wallet','Other'].map(v=>`<option ${type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Business Unit</label><select name="business_unit_id"><option value="">Company-wide</option>${(unitOptions||[]).map(u=>`<option value="${u.id}" ${Number(x?.business_unit_id)===Number(u.id)?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Currency *</label><select name="currency" required>${['KRW','USD','PKR','EUR','JPY','CNY'].map(v=>`<option ${String(x?.currency||'KRW')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field v320-country-field"><label>Bank Country / Account Country *</label><select name="account_country"><option value="">Select account country</option>${['South Korea','Pakistan','United States','United Arab Emirates','China','Japan','Other'].map(v=>`<option value="${v}" ${String(x?.account_country||'')===v?'selected':''}>${v}</option>`).join('')}</select><small class="muted">Country is separate from currency and controls country-specific payment eligibility.</small></div><div class="field"><label>GL Account *</label><select name="ledger_account_id" required><option value="">Select GL mapping</option>${ledgers.map(a=>`<option value="${a.id}" ${Number(x?.ledger_account_id)===Number(a.id)?'selected':''}>${esc(a.code+' · '+a.name+' · '+a.account_type)}</option>`).join('')}</select></div><div class="field v320-bank-field"><label>Bank / Issuer</label><input name="bank_name" value="${esc(x?.bank_name||'')}"></div><div class="field v320-bank-field"><label>Account Holder</label><input name="account_holder" value="${esc(x?.account_holder||'')}"></div><div class="field v320-bank-field"><label>Account Number</label><input name="account_number" value="${esc(x?.account_number||'')}"></div><div class="field v320-bank-field"><label>IBAN</label><input name="iban" value="${esc(x?.iban||'')}"></div><div class="field v320-bank-field"><label>SWIFT / BIC</label><input name="swift_bic" value="${esc(x?.swift_bic||'')}"></div><div class="field v320-bank-field"><label>Branch</label><input name="branch" value="${esc(x?.branch||'')}"></div><div class="field v320-bank-field"><label>Cheque Enabled</label><select name="cheque_enabled"><option value="0" ${!Number(x?.cheque_enabled||0)?'selected':''}>No</option><option value="1" ${Number(x?.cheque_enabled||0)?'selected':''}>Yes</option></select></div><div class="field v320-card-field"><label>Card Network</label><input name="card_network" placeholder="Visa / Mastercard / etc." value="${esc(x?.card_network||'')}"></div><div class="field v320-card-field"><label>Card Last 4</label><input name="card_last4" maxlength="4" inputmode="numeric" pattern="[0-9]{4}" value="${esc(x?.card_last4||'')}"></div><div class="field v320-card-field"><label>Card Expiry</label><input name="card_expiry" placeholder="MM/YY" value="${esc(x?.card_expiry||'')}"></div><div class="field v320-card-field"><label>Linked Bank Account</label><select name="linked_bank_account_id"><option value="">None</option>${banks.map(a=>`<option value="${a.id}" ${Number(x?.linked_bank_account_id)===Number(a.id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Default Payment Account</label><select name="default_payment"><option value="0" ${!Number(x?.default_payment||0)?'selected':''}>No</option><option value="1" ${Number(x?.default_payment||0)?'selected':''}>Yes</option></select></div><div class="field"><label>Default Receipt Account</label><select name="default_receipt"><option value="0" ${!Number(x?.default_receipt||0)?'selected':''}>No</option><option value="1" ${Number(x?.default_receipt||0)?'selected':''}>Yes</option></select></div><div class="field full"><label>Notes</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="field full"><label>${id?'Change':'Creation'} Reason *</label><textarea name="reason" required></textarea></div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${id?'Review & Update':'Review & Create'}</button></div></form>`,'wide');financialAccountTypeV320(document.querySelector('#modalRoot form'))}catch(e){toast(e.message)}};
window.financialAccountTypeV320=function(f){if(!f)return;const type=f.financial_account_type.value;f.querySelectorAll('.v320-bank-field').forEach(el=>el.style.display=['Bank','Card'].includes(type)?'block':'none');f.querySelectorAll('.v320-card-field').forEach(el=>el.style.display=type==='Card'?'block':'none');const country=f.querySelector('[name="account_country"]');if(country)country.required=type==='Bank'};
window.saveFinancialAccountV320=async function(e,id){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const o=Object.fromEntries(new FormData(f));o.business_unit_id=o.business_unit_id||null;o.ledger_account_id=Number(o.ledger_account_id);o.linked_bank_account_id=o.linked_bank_account_id?Number(o.linked_bank_account_id):null;o.cheque_enabled=o.cheque_enabled==='1';o.default_payment=o.default_payment==='1';o.default_receipt=o.default_receipt==='1';const ok=await confirmAction({title:id?'Update Financial Account':'Create Financial Account',message:'This account will become part of the controlled payment and Accounting configuration.',confirmLabel:id?'Update Account':'Create Account',tone:'danger',details:[{label:'Name',value:o.name},{label:'Type',value:o.financial_account_type},{label:'Currency',value:o.currency},{label:'Account Country',value:o.account_country||'—'},{label:'Reason',value:o.reason}]});if(!ok)return;try{await api('/api/v320/financial-accounts'+(id?'/'+id:''),{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal(true);toast('Financial account saved');renderFinancialAccountsV320()}catch(x){if(id&&/transaction history/i.test(x.message||'')&&me.role==='CEO / Owner'){const confirm=await confirmAction({title:'High-risk GL Mapping Change',message:x.message,confirmLabel:'Confirm Mapping Change',tone:'danger'});if(confirm){o.confirm_existing_transactions=true;try{await api('/api/v320/financial-accounts/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal(true);toast('Financial account updated with CEO confirmation');renderFinancialAccountsV320()}catch(y){toast(y.message)}}}else toast(x.message)}};
window.closeFinancialAccountV320=async function(id,name,status='Closed'){const action=status==='Archived'?'Archive':'Close';const reason=await reasonAction({title:action+' Financial Account',message:'The account will be unavailable for new transactions, while all historical Finance and Accounting references remain preserved.',confirmLabel:action+' Account',tone:status==='Archived'?'primary':'danger',details:[{label:'Account',value:name},{label:'New Status',value:status}]});if(reason===null)return;try{await api('/api/v320/financial-accounts/'+id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,reason})});toast('Financial account '+status.toLowerCase()+'; history preserved');renderFinancialAccountsV320()}catch(e){toast(e.message)}};
window.financialAccountHistoryV320=async function(id){try{const rows=await api('/api/v320/financial-accounts/'+id+'/history');modal(`<h2>Financial Account History</h2><div class="v319-settings-history">${rows.map(r=>`<div class="v319-history-item"><b>${esc(r.changed_at||r.created_at||'')} · ${esc(r.changed_by_name||'System')}</b><div>${esc(r.reason||'')}</div><small class="muted">Before: ${esc(JSON.stringify(r.before||{}))}</small><small class="muted">After: ${esc(JSON.stringify(r.after||{}))}</small></div>`).join('')||'<div class="empty">No history yet.</div>'}</div><div class="actions"><button class="btn" onclick="closeModal()">Close</button></div>`,'wide')}catch(e){toast(e.message)}};

// UI-first Supplier / Buyer contact validation.
function phoneLocalV320(v){const raw=String(v||'').trim();if(!raw)return '';const digits=raw.replace(/\D/g,'');if(!/^\+?[0-9][0-9\s().-]{5,24}$/.test(raw)||digits.length<6||digits.length>15)return 'Enter a valid phone number (6–15 digits).';return ''}
function emailLocalV320(v){const raw=String(v||'').trim();if(!raw)return '';return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(raw)?'':'Enter a valid email address.'}
function contactEntityV320(f){const s=String(f.getAttribute('onsubmit')||'');return s.includes('Supplier')?'supplier':s.includes('Buyer')?'buyer':''}
function contactIdV320(f){const m=String(f.getAttribute('onsubmit')||'').match(/\(event\s*,\s*(\d+)/);return Number(m?.[1]||0)}
function showContactErrorV320(input,msg,ok=false){input.setCustomValidity(msg||'');input.classList.toggle('v320-invalid',!!msg);let e=input.parentElement?.querySelector('.v320-validation');if(!e){e=document.createElement('small');e.className='v320-validation';input.insertAdjacentElement('afterend',e)}e.textContent=msg||(ok?'Looks good.':'');e.className='v320-validation '+(msg?'bad':ok?'ok':'')}
let contactTimersV320=new WeakMap();
async function validateContactFieldV320(input,remote=true){if(input?.dataset?.v321Phone==='1'||input?.dataset?.v321Email==='1')return true;const f=input.form,entity=contactEntityV320(f);if(!entity)return true;const field=input.name,local=field==='phone'?phoneLocalV320(input.value):emailLocalV320(input.value);if(local){showContactErrorV320(input,local);return false}showContactErrorV320(input,'');if(!remote||!String(input.value||'').trim())return true;try{const q=new URLSearchParams({entity,business_unit_id:String(selectedUnitId||me.business_unit_id||''),exclude_id:String(contactIdV320(f)),[field]:String(input.value||'').trim()});const r=await api('/api/v320/contact-check?'+q.toString());if(!r.valid&&r.field===field){showContactErrorV320(input,r.message||'Invalid value.');return false}showContactErrorV320(input,'',true);return true}catch(e){showContactErrorV320(input,e.message||'Could not validate.');return false}}
function enhanceContactFormV320(f){if(f.dataset.v320Contact==='1')return;const entity=contactEntityV320(f);if(!entity)return;f.dataset.v320Contact='1';for(const name of ['phone','email']){const input=f.querySelector(`[name="${name}"]`);if(!input)continue;if(name==='phone'){input.type='tel';input.inputMode='tel';input.autocomplete='tel'}else{input.type='email';input.autocomplete='email'}input.addEventListener('input',()=>{const prior=contactTimersV320.get(input);if(prior)clearTimeout(prior);validateContactFieldV320(input,false);contactTimersV320.set(input,setTimeout(()=>validateContactFieldV320(input,true),450))});input.addEventListener('blur',()=>validateContactFieldV320(input,true))}}
async function validateContactFormV320(f){enhanceContactFormV320(f);const fields=[...f.querySelectorAll('[name="phone"],[name="email"]')];const ok=(await Promise.all(fields.map(i=>validateContactFieldV320(i,true)))).every(Boolean);if(!ok)f.reportValidity();return ok}
const saveSupplierOriginal=window.saveExcavatorSupplier;
if(saveSupplierOriginal)window.saveExcavatorSupplier=async function(e,id){e.preventDefault();if(!(await validateContactFormV320(e.target)))return;return saveSupplierOriginal(e,id)};
const saveBuyerOriginal=window.saveExcavatorBuyer;
if(saveBuyerOriginal)window.saveExcavatorBuyer=async function(e,id){e.preventDefault();if(!(await validateContactFormV320(e.target)))return;return saveBuyerOriginal(e,id)};

// Smart payment routing: method controls the only valid account choices.
const paymentNames=['payment_method','method','mode_of_payment'];
function methodInputV320(f){return paymentNames.map(n=>f.querySelector(`[name="${n}"]`)).find(Boolean)}
function accountInputV320(f){return f.querySelector('[name="payment_account_id"]')}
function referenceInputV320(f){return f.querySelector('[name="payment_reference"],[name="reference"]')}
function smartAccountLabelV320(method){const k=String(method||'').toLowerCase();if(k.includes('cash'))return 'Cash Account';if(k.includes('card'))return 'Company Card';if(k.includes('cheque')||k.includes('check'))return 'Cheque Bank Account';return 'Company Bank / Payment Account'}
async function refreshSmartPaymentV320(f,preserve=true){const method=methodInputV320(f),sel=accountInputV320(f);if(!method||!sel)return;const methodText=String(method.value||'').trim(),internal=/credit( note)?|advance balance|buyer advance|supplier credit|receivable|unallocated|allocation/i.test(methodText);const accountField=sel.closest('.field');if(internal){sel.required=false;sel.disabled=true;sel.setCustomValidity('');if(accountField)accountField.style.display='none';const ref=referenceInputV320(f);if(ref)ref.required=false;return}else{sel.disabled=false;if(accountField)accountField.style.display='block'}const old=preserve?Number(sel.value||0):0,bu=Number(f.querySelector('[name="business_unit_id"]')?.value||selectedUnitId||me.business_unit_id||0);let d;try{const params={business_unit_id:String(bu),method:String(method.value||'Bank')};const country=String(f.dataset.accountCountry||sel.dataset.accountCountry||'').trim(),currency=String(f.dataset.accountCurrency||sel.dataset.accountCurrency||'').trim(),direction=String(f.dataset.accountDirection||sel.dataset.accountDirection||'').trim();if(country)params.country=country;if(currency)params.currency=currency;if(direction)params.direction=direction;d=await api('/api/v320/financial-accounts/options?'+new URLSearchParams(params))}catch(e){sel.innerHTML='<option value="">No compatible account configured</option>';sel.setCustomValidity(e.message);return}sel.innerHTML=(d.accounts||[]).map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.financial_account_type)} · ${esc(a.currency||'KRW')}${a.account_number_masked?' · '+esc(a.account_number_masked):''}</option>`).join('')||'<option value="">No compatible account configured</option>';const available=[...(d.accounts||[])].map(a=>Number(a.id));sel.value=available.includes(old)?String(old):String(d.default_account_id||available[0]||'');sel.required=true;sel.setCustomValidity(sel.value?'':'Configure an active '+(d.wanted_type||'payment')+' account in System Settings → Company Financial Accounts.');const field=sel.closest('.field');const label=field?.querySelector('label');if(label)label.textContent=smartAccountLabelV320(method.value)+' *';let hint=field?.querySelector('.v320-payment-hint');if(!hint&&field){hint=document.createElement('small');hint.className='v320-payment-hint';field.appendChild(hint)}if(hint){hint.textContent=(d.accounts||[]).length?`Showing only active ${d.wanted_type} accounts allowed for this payment method.`:`No active compatible account. Add one in System Settings → Company Financial Accounts.`;hint.classList.toggle('bad',!(d.accounts||[]).length)}const ref=referenceInputV320(f),cash=/cash/i.test(method.value||'');if(ref){ref.required=!cash;ref.placeholder=cash?'Optional for cash':'Required for non-cash';ref.setCustomValidity(!cash&&!String(ref.value||'').trim()?'Payment reference is required for non-cash payments.':'')}}
function enhancePaymentFormV320(f){if(f.dataset.v320Payment==='1')return;const method=methodInputV320(f);if(!method)return;let sel=accountInputV320(f);if(!sel){const methodField=method.closest('.field')||method.parentElement;if(methodField){const box=document.createElement('div');box.className='field v320-auto-account';box.innerHTML='<label>Company Financial Account *</label><select name="payment_account_id" required></select><small class="v320-payment-hint"></small>';methodField.insertAdjacentElement('afterend',box);sel=box.querySelector('select')}}if(!sel)return;f.dataset.v320Payment='1';method.addEventListener('change',()=>refreshSmartPaymentV320(f,false));const bu=f.querySelector('[name="business_unit_id"]');if(bu)bu.addEventListener('change',()=>refreshSmartPaymentV320(f,false));const ref=referenceInputV320(f);if(ref)ref.addEventListener('input',()=>{const cash=/cash/i.test(method.value||'');ref.setCustomValidity(!cash&&!String(ref.value||'').trim()?'Payment reference is required for non-cash payments.':'')});refreshSmartPaymentV320(f,true)}


function internalPaymentMethodV320(method){return /^(credit|receivable|payable|buyer advance|advance balance|supplier credit|allocation)$/i.test(String(method||'').trim())}
function financialAccountLabelV320(a){return [a.name,a.financial_account_type,a.currency,a.account_number_masked||a.card_last4].filter(Boolean).join(' · ')}
async function chooseFinancialAccountV320(method,businessUnitId){
  if(internalPaymentMethodV320(method))return null;
  const bu=Number(businessUnitId||selectedUnitId||me?.business_unit_id||0);
  const d=await api('/api/v320/financial-accounts/options?'+new URLSearchParams({business_unit_id:String(bu),method:String(method||'Cash')}));
  const accounts=d.accounts||[];
  if(!accounts.length)throw new Error(`No active ${d.wanted_type||'compatible'} Company Financial Account is configured for ${method}. Add one in System Settings → Company Financial Accounts.`);
  if(accounts.length===1)return Number(accounts[0].id);
  const selected=await choiceAction({title:'Select Company Financial Account',message:`Choose the exact ${d.wanted_type||'financial'} account used for this ${method} payment.`,label:'Company Financial Account',options:accounts.map(a=>({value:String(a.id),label:financialAccountLabelV320(a)})),defaultValue:String(d.default_account_id||accounts[0].id),confirmLabel:'Use Account'});
  return selected===null?null:Number(selected);
}

// MIMI POS uses the same smart Company Financial Account routing as every other payment flow.
window.saveROrder=async function(){
  if(!window._rItems?.length)return toast('Add menu items');
  try{
    const type=document.getElementById('rType').value,table=document.getElementById('rTable').value;
    if(type==='Dine-in'&&!table)return toast('Select an available table');
    const method=document.getElementById('rPayment').value,accountId=await chooseFinancialAccountV320(method,selectedUnitId||me?.business_unit_id);
    if(!internalPaymentMethodV320(method)&&accountId===null)return;
    const d=await api('/api/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:table||null,order_type:type,customer_name:document.getElementById('rCustomer').value,items:window._rItems})});
    const sale=await api('/api/restaurant/orders/'+d.id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:method,payment_account_id:accountId})});
    if(sale.approval_required){toast(sale.message||'Sale submitted for approval. The restaurant order remains open.');loadView();return}
    closeModal();toast('Order closed and posted');loadView();if(sale.id)printReceipt(d.id);
  }catch(x){toast(x.message)}
};
window.closeOpenOrder=async function(id){
  const pay=await choiceAction({title:'Close & Pay Order',message:'Select the payment method before finalizing this order.',label:'Payment Method',options:['Cash','Card','Bank','Credit'],defaultValue:'Cash',confirmLabel:'Continue',details:[{label:'Order',value:'#'+id}]});if(pay===null)return;
  try{
    const accountId=await chooseFinancialAccountV320(pay,selectedUnitId||me?.business_unit_id);if(!internalPaymentMethodV320(pay)&&accountId===null)return;
    await api('/api/restaurant/orders/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_type:document.getElementById('erType').value,table_id:document.getElementById('erTable').value||null,customer_name:document.getElementById('erCustomer').value,items:window._rEditItems})});
    const d=await api('/api/restaurant/orders/'+id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:pay,payment_account_id:accountId})});
    if(d.approval_required)return toast(d.message||'Sale submitted for approval. The order remains open.');closeModal();toast('Order closed and posted');loadView();if(d.id)printReceipt(d.id)
  }catch(x){toast(x.message)}
};
window.v320ChooseFinancialAccount=chooseFinancialAccountV320;

// Direct attachment upload: no upload-time preview/compression/optimization.
let v320AttachmentPolicyCache=null;
async function attachmentPolicyV320(){if(v320AttachmentPolicyCache)return v320AttachmentPolicyCache;try{v320AttachmentPolicyCache=await api('/api/v320/attachment-policy?'+new URLSearchParams({business_unit_id:String(selectedUnitId||me.business_unit_id||'')}))}catch(_){v320AttachmentPolicyCache={max_file_size_mb:20,max_attachments_per_upload:30,allowed_file_types:'pdf,jpg,jpeg,png,webp,xlsx,xls,csv,doc,docx'}}return v320AttachmentPolicyCache}
async function enhanceFileInputV320(input){if(input.dataset.v320File==='1')return;input.dataset.v320File='1';const p=await attachmentPolicyV320(),types=String(p.allowed_file_types||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);input.accept=types.map(x=>'.'+x.replace(/^\./,'')).join(',');let help=input.parentElement?.querySelector('.v320-file-help');if(!help){help=document.createElement('small');help.className='v320-file-help';input.insertAdjacentElement('afterend',help)}const maxCount=input.multiple?Math.max(1,Number(input.dataset.maxFiles||p.max_attachments_per_upload||30)):1;help.textContent=`Allowed: ${types.map(x=>x.toUpperCase()).join(', ')} · Max ${Number(p.max_file_size_mb||20)} MB per file · ${maxCount===1?'1 file only':`Max ${maxCount} files per upload`}.`;let err=input.parentElement?.querySelector('.v320-file-error');if(!err){err=document.createElement('small');err.className='v320-file-error';help.insertAdjacentElement('afterend',err)}input.addEventListener('change',()=>{const files=[...(input.files||[])],maxCount=input.multiple?Math.max(1,Number(input.dataset.maxFiles||p.max_attachments_per_upload||30)):1,maxBytes=Number(p.max_file_size_mb||20)*1024*1024;let msg='';if(files.length>maxCount)msg=`Select no more than ${maxCount} files per upload.`;if(!msg){const bad=files.find(f=>f.size>maxBytes);if(bad)msg=`${bad.name} exceeds the ${p.max_file_size_mb} MB file-size limit.`}if(!msg){const bad=files.find(f=>{const ext=(f.name.split('.').pop()||'').toLowerCase();return types.length&&!types.includes(ext)});if(bad)msg=`${bad.name} is not an allowed file format.`}input.setCustomValidity(msg);err.textContent=msg;if(msg)input.classList.add('v320-invalid');else input.classList.remove('v320-invalid')})}

function enhanceAllV320(root=document){root.querySelectorAll?.('form[onsubmit*="saveExcavatorSupplier"],form[onsubmit*="saveExcavatorBuyer"]').forEach(enhanceContactFormV320);root.querySelectorAll?.('form').forEach(enhancePaymentFormV320);root.querySelectorAll?.('input[type="file"]').forEach(enhanceFileInputV320)}
window.BOMMutationHub.register('v320-enhancements',enhanceAllV320,{root:'body'});enhanceAllV320(document);

