const flag=iso=>iso.toUpperCase().replace(/./g,c=>String.fromCodePoint(127397+c.charCodeAt()));
const countryAliases={'korea':'KR','south korea':'KR','republic of korea':'KR','pakistan':'PK','uae':'AE','united arab emirates':'AE','usa':'US','united states of america':'US','uk':'GB','england':'GB','great britain':'GB'};
function countryFromText(v){const s=String(v||'').trim().toLowerCase();if(!s)return null;if(countryAliases[s])return C.find(x=>x[0]===countryAliases[s])||null;return C.find(x=>x[1].toLowerCase()===s)||C.find(x=>x[1].toLowerCase().includes(s)||s.includes(x[1].toLowerCase()))||null}
function countryFromE164(v){const d=String(v||'').replace(/\D/g,'');return [...C].sort((a,b)=>b[2].length-a[2].length).find(x=>d.startsWith(x[2]))||null}
function companionCountryField(input){const f=input.form;if(!f)return null;const n=input.dataset.v321OriginalName||input.name||'',prefix=n.replace(/(?:mobile_?)?phone$/i,'').replace(/_$/,'');const selectors=[prefix?`[name="${prefix}_country"]`:null,n.startsWith('new_buyer_')?'[name="new_buyer_country"]':null,n.startsWith('supplier_')?'[name="supplier_country"]':null,'[name="country"]','[name="buyer_country"]','[name="customer_country"]'].filter(Boolean);return selectors.map(s=>f.querySelector(s)).find(Boolean)||null}
function phoneEntity(input){const n=String(input.dataset.v321OriginalName||input.name||'').toLowerCase(),s=String(input.form?.getAttribute('onsubmit')||'').toLowerCase();if(n.includes('supplier')||s.includes('supplier'))return 'supplier';if(n.includes('buyer')||s.includes('buyer'))return 'buyer';if(s.includes('employee'))return 'employee';if(s.includes('customer')||n.includes('customer'))return 'customer';if(s.includes('user'))return 'user';return ''}
