    if(mode!=='keep'&&(source==='new_payment'||source==='advance_plus_new')){const method=String(fd.get('payment_method')||''),cur=String(fd.get('payment_currency')||'KRW'),fx=cur==='KRW'?1:Number(fd.get('payment_fx_rate')||0),orig=Number(fd.get('payment_amount')||0);received=cur==='KRW'?orig:orig*fx;if(!(orig>0))throw new Error('Payment Amount is required.');if(!fd.get('payment_date'))throw new Error('Payment Date is required.');if(method.toLowerCase()!=='cash'&&!fd.get('payment_reference'))throw new Error('Payment Reference is required for non-cash payments.');if(!form.querySelector('[name="payment_evidence"]')?.files.length)throw new Error('Receipt / evidence is mandatory for a newly received payment.');if(received+0.005<newNeeded)throw new Error(`New payment is short by ${m(newNeeded-received)}.`)}
