function injectFinanceAccountV329(d){const wf=workflow(),f=d?.finance||d?.record||{},acct=d?.payment_account;if(!wf)return;wf.querySelectorAll('[data-v329-finance-account]').forEach(x=>x.remove());const cards=[...wf.querySelectorAll('.card')],card=cards.find(x=>/Financial Record/i.test(x.textContent||''))||cards[0];if(!card)return;const hasCashEffect=f.cash_effect!==null&&f.cash_effect!==undefined&&String(f.cash_effect)!=='',incoming=hasCashEffect?Number(f.cash_effect)>0:String(f.type||'').toLowerCase()==='revenue',label=incoming?t('Received Into'):t('Paid From'),box=document.createElement('div');box.dataset.v329FinanceAccount='1';box.className='v329-verification-account'+(!acct?' v329-account-warning':'');if(acct){const institution=acct.bank_name||acct.financial_institution||'';box.innerHTML=`<small>${esc(label)}</small><div class="v329-account-line"><b>${esc(acct.name||acct.account_name||'Financial Account')}</b><span class="pill blue">${esc(acct.financial_account_type||acct.account_type||'')}</span><span>${esc(acct.currency||'')}</span></div><div class="muted">${[institution,acct.bank_country||acct.account_country,acct.account_number_masked].filter(Boolean).map(esc).join(' · ')}</div>`}else box.innerHTML=`<small>${esc(label)}</small><b>${esc(t('Financial account not recorded'))}</b><div class="muted">Verify the source transaction before approval. A real cash movement should identify the company account used.</div>`;card.appendChild(box);try{translateElement(box)}catch(_){ }}

