let dedupeTimer=null;function dedupePakistanV329(){const wf=document.getElementById('v324WorkflowSurface');if(!wf)return;const all=[...wf.querySelectorAll('button,a')].filter(b=>{const x=String(b.textContent||'').trim().toLowerCase();return x==='pakistan resales'||b.dataset?.v327PakistanResales==='1'});if(!all.length)return;const statement=[...wf.querySelectorAll('button,a')].find(b=>/buyer statement/i.test(String(b.textContent||'')));const preferred=statement?.parentElement||all[0].parentElement,keep=all[0];all.slice(1).forEach(x=>x.remove());if(preferred&&keep.parentElement!==preferred)preferred.appendChild(keep)}function scheduleDedupe(){clearTimeout(dedupeTimer);dedupeTimer=setTimeout(dedupePakistanV329,20);setTimeout(dedupePakistanV329,120);setTimeout(dedupePakistanV329,400)}

