function upgradeResalePaymentV329(root=document){const form=root.querySelector?.('[data-v327-payment-form]')||root.querySelector?.('form');if(!form||!form.closest?.('#modalRoot')||!form.textContent.includes('Payment Allocations'))return;if(form.querySelector('.v327-allocation-check'))return;const amountInput=form.querySelector('[name="amount_pkr"]');if(!amountInput)return;const rows=[...form.querySelectorAll('[data-resale-id]')];for(const row of rows){if(row.querySelector('.v329-resale-check'))continue;const rid=Number(row.dataset.resaleId||0),manual=row.querySelector('.v327-allocation-input'),out=Number(manual?.max||manual?.dataset?.outstanding||row.dataset.outstanding||0);if(manual){manual.style.display='none';manual.tabIndex=-1}const host=manual?.closest('.field')||row;const label=document.createElement('label');label.className='v329-resale-check';label.innerHTML=`<input type="checkbox" class="v329-resale-auto-check" data-resale-id="${rid}" data-outstanding="${out}"><span>Select machine</span><span class="v329-allocation-preview" data-v329-allocation="${rid}">${pkr(0)}</span>`;host.prepend(label)}
  const update=()=>{let remaining=Number(amountInput.value||0),allocated=0;for(const cb of form.querySelectorAll('.v329-resale-auto-check')){const out=Number(cb.dataset.outstanding||0),take=cb.checked?Math.min(out,remaining):0;cb.closest('[data-resale-id]')?.classList.toggle('v329-selected',cb.checked);const preview=form.querySelector(`[data-v329-allocation="${cb.dataset.resaleId}"]`);if(preview)preview.textContent=pkr(take);const old=form.querySelector(`.v327-allocation-input[data-resale-id="${cb.dataset.resaleId}"]`);if(old)old.value=take?String(take):'';remaining=Math.max(0,remaining-take);allocated+=take}const allocatedEl=form.querySelector('[data-v327-allocated-total]'),creditEl=form.querySelector('[data-v327-unallocated-total]');if(allocatedEl)allocatedEl.textContent=pkr(allocated);if(creditEl)creditEl.textContent=pkr(Math.max(0,Number(amountInput.value||0)-allocated))};amountInput.addEventListener('input',update);form.addEventListener('change',e=>{if(e.target.matches('.v329-resale-auto-check'))update()});update();
  const btn=[...form.querySelectorAll('button')].find(b=>/Review\s*&\s*Confirm/i.test(b.textContent||''));if(btn){btn.type='button';btn.onclick=async()=>{update();try{const fd=new FormData(form),amount=Number(fd.get('amount_pkr')||0);if(!(amount>0))throw new Error('Payment amount must be greater than zero.');const selected=[...form.querySelectorAll('.v329-resale-auto-check:checked')];if(!selected.length)throw new Error('Select at least one machine for allocation, or leave the payment as unallocated credit only if the workflow explicitly permits it.');const allocations=selected.map(cb=>{const el=form.querySelector(`.v327-allocation-input[data-resale-id="${cb.dataset.resaleId}"]`);return {resale_id:Number(cb.dataset.resaleId),amount_pkr:Number(el?.value||0)}}).filter(x=>x.amount_pkr>0),allocated=allocations.reduce((n,x)=>n+x.amount_pkr,0),account=form.querySelector('[name="payment_account_id"]'),details=[{label:'Payment',value:pkr(amount)},{label:'Receive Into',value:selectedText(account)||'—'},{label:'Reference',value:String(fd.get('reference')||'—')},{label:'Allocated to Resales',value:pkr(allocated)},{label:'Unallocated Credit',value:pkr(Math.max(0,amount-allocated))},...allocations.map(x=>({label:'Machine Allocation',value:`#${x.resale_id} · ${pkr(x.amount_pkr)}`}))];const ok=await confirmAction({title:'Review & Confirm Resale Profit Payment',message:'Verify the Pakistan account, evidence and automatic machine allocations before recording this receipt.',confirmLabel:'Confirm Payment',details});if(!ok)return;fd.set('allocations',JSON.stringify(allocations));const endpoint=form.dataset.endpoint||form.getAttribute('action')||'';if(!endpoint)throw new Error('Payment endpoint is unavailable.');btn.disabled=true;btn.textContent='Recording…';const out=await multipartApi(endpoint,fd);if(out.approval_required){btn.disabled=false;btn.textContent='Review & Confirm';return toast(out.message||'Approval required.')}if(typeof closeModalAfterSave==='function')closeModalAfterSave();else closeModal(true);toast('Resale profit payment recorded');const buyerId=Number(form.dataset.buyerId||0);if(buyerId)excavatorBuyerDetail(buyerId);scheduleDataSync?.()}catch(e){btn.disabled=false;btn.textContent='Review & Confirm';toast(e.message)}}}
}

