const buyerPaymentFormBeforeV330=window.excavatorBuyerPaymentForm;
if(typeof buyerPaymentFormBeforeV330==='function')window.excavatorBuyerPaymentForm=async function(){const r=await buyerPaymentFormBeforeV330.apply(this,arguments);const f=document.querySelector('#modalRoot form');if(f)setAccountContext(f,{country:'South Korea',direction:'receipt'});return r};

// Finance Verification shows both the company side and receiver side.
const financeOpenBeforeV330=window.financeOpen;
if(typeof financeOpenBeforeV330==='function')window.financeOpen=async function(id){const r=await financeOpenBeforeV330.apply(this,arguments);try{const d=await api('/api/finance/'+id+'/detail');injectReceiverV330(d)}catch(e){console.warn('V30.30 receiver verification',e.message)}return r};
function injectReceiverV330(d){const host=wf(),f=d?.finance||{},receiver=d?.receiver_account;if(!host||Number(f.cash_effect||0)>=0)return;host.querySelectorAll('[data-v330-receiver-verify]').forEach(x=>x.remove());const existing=host.querySelector('[data-v329-finance-account]'),card=existing?.parentElement||[...host.querySelectorAll('.card')].find(x=>/Financial Record/i.test(x.textContent||''));if(!card)return;const box=document.createElement('div');box.dataset.v330ReceiverVerify='1';box.className='v329-verification-account'+(!receiver&&/bank|card|cheque|wallet/i.test(f.payment_method||'')?' v329-account-warning':'');box.innerHTML=receiver?`<small>${esc(t('Paid To'))}</small><div class="v329-account-line"><b>${esc(receiver.name||receiver.label||'Receiver')}</b><span class="pill blue">${esc(receiver.method_type||'')}</span><span>${esc(receiver.currency||'')}</span></div><div class="muted">${[receiver.label,receiver.bank_name,receiver.account_country,receiver.account_number_masked].filter(Boolean).map(esc).join(' · ')}</div>`:`<small>${esc(t('Paid To'))}</small><b>Receiver account not recorded</b><div class="muted">For bank/card/electronic outgoing payments, verify the destination account before approving this record.</div>`;card.appendChild(box);try{translateElement(box)}catch(_){ }}

// Pakistan Resale buyer-level pooled credit actions.
const resaleOpenBeforeV330=window.openPakistanResalesV327;
if(typeof resaleOpenBeforeV330==='function')window.openPakistanResalesV327=async function(buyerId){const r=await resaleOpenBeforeV330.apply(this,arguments);setTimeout(()=>enhanceResaleCreditV330(buyerId),30);return r};
async function enhanceResaleCreditV330(buyerId){try{const s=await api(`/api/v330/excavator/buyers/${buyerId}/resale-credit-summary`),host=wf();if(!host)return;const stats=host.querySelector('.v327-summary');if(stats&&!stats.querySelector('[data-v330-credit-stat]'))stats.insertAdjacentHTML('beforeend',`<div class="v327-stat" data-v330-credit-stat><small>${esc(t('Total Received'))}</small><b>${pkr(s.total_received_pkr)}</b></div><div class="v327-stat" data-v330-credit-stat><small>${esc(t('Total Refunded'))}</small><b>${pkr(s.refunded_pkr)}</b></div>`);const section=[...host.querySelectorAll('.v327-section')].find(x=>/Resale Profit Payments/i.test(x.textContent||''));const title=section?.querySelector('.section-title');if(title&&!title.querySelector('[data-v330-credit-actions]')){const a=document.createElement('div');a.className='v330-credit-actions';a.dataset.v330CreditActions='1';a.innerHTML=`<button class="btn" onclick="allocateResaleCreditV330(${buyerId})">${esc(t('Allocate Credit'))}</button><button class="btn" ${Number(s.available_credit_pkr||0)>.005?'':'disabled'} onclick="refundResaleCreditV330(${buyerId})">${esc(t('Refund Credit'))}</button><button class="btn primary" onclick="combinedResaleSettlementV330(${buyerId})">${esc(t('Settle with Credit + New Payment'))}</button>`;title.appendChild(a)}try{translateElement(host)}catch(_){ }}catch(e){console.warn(e.message)}}
function targetRows(resales){return (resales||[]).filter(r=>Number(r.outstanding_pkr||0)>.005&&r.settlement_status!=='Voided').map(r=>`<label class="v330-target"><input type="checkbox" name="resale_id" value="${r.id}"><div><b>${esc(r.asset_no||'Machine')} · ${esc(r.machine_name||'')}</b><div class="muted">Share ${pkr(r.our_share_pkr)}</div></div><div><small>Outstanding</small><b>${pkr(r.outstanding_pkr)}</b></div><div><span class="pill warn">${esc(r.settlement_status||'Share Due')}</span></div></label>`).join('')||'<div class="empty">No machine resale balances are outstanding.</div>'}
window.allocateResaleCreditV330=async function(buyerId){try{const [d,s]=await Promise.all([api(`/api/v327/excavator/buyers/${buyerId}/pakistan-resales`),api(`/api/v330/excavator/buyers/${buyerId}/resale-credit-summary`)]);modal(`<h2>${esc(t('Allocate Credit'))}</h2><p class="muted">Allocate already-received unallocated Pakistan resale credit. This creates <b>no new Finance receipt</b>.</p><form onsubmit="saveAllocateResaleCreditV330(event,${buyerId})"><div class="workspace-banner"><b>${esc(t('Available Credit'))}: ${pkr(s.available_credit_pkr)}</b></div><div class="field"><label>Maximum Credit to Allocate (PKR)</label><input name="amount_pkr" type="number" min="0.01" max="${Number(s.available_credit_pkr||0)}" step="0.01" value="${Number(s.available_credit_pkr||0)}" required></div>${targetRows(d.resales)}<div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Review & Confirm</button></div></form>`,'wide')}catch(e){toast(e.message)}};
window.saveAllocateResaleCreditV330=async function(e,buyerId){e.preventDefault();const f=e.target,ids=[...f.querySelectorAll('[name="resale_id"]:checked')].map(x=>Number(x.value));if(!ids.length)return toast('Select at least one machine.');const amount=Number(f.amount_pkr.value||0),ok=await confirmAction({title:'Allocate Existing Pakistan Resale Credit',message:'This uses money already received. No new Finance receipt will be created.',confirmLabel:'Allocate Credit',details:[{label:'Credit to use',value:pkr(amount)},{label:'Selected machines',value:String(ids.length)}]});if(!ok)return;try{await api(`/api/v330/excavator/buyers/${buyerId}/resale-credit/allocate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resale_ids:ids,amount_pkr:amount})});closeModalAfterSave();toast('Existing resale credit allocated');openPakistanResalesV327(buyerId);scheduleDataSync?.()}catch(x){toast(x.message)}};

window.refundResaleCreditV330=async function(buyerId){try{const [d,s,accounts,payees]=await Promise.all([api(`/api/v327/excavator/buyers/${buyerId}/pakistan-resales`),api(`/api/v330/excavator/buyers/${buyerId}/resale-credit-summary`),countryAccountsV327('Pakistan','payment'),payeeAccounts('excavator_buyer',buyerId,'Bank')]);modal(`<h2>${esc(t('Refund Unallocated Credit'))}</h2><p class="muted">Refund buyer-level unallocated resale credit. This is one real outgoing Finance payment and consumes the oldest available credit sources first.</p><form data-account-country="Pakistan" data-account-currency="PKR" data-account-direction="payment" onsubmit="saveRefundResaleCreditV330(event,${buyerId})" enctype="multipart/form-data"><div class="workspace-banner"><b>${esc(t('Available Credit'))}: ${pkr(s.available_credit_pkr)}</b></div><div class="grid g2"><div class="field"><label>Refund Amount (PKR) *</label><input name="amount_pkr" type="number" min="0.01" max="${Number(s.available_credit_pkr||0)}" step="0.01" required></div><div class="field"><label>FX Rate to KRW *</label><input name="fx_rate_to_krw" type="number" min="0.000001" step="0.000001" required></div><div class="field"><label>Refund Date *</label><input name="refund_date" type="date" value="${today()}" required></div><div class="field"><label>Pay From · Pakistan Company Account *</label><select name="payment_account_id" required>${accountOptionsV327(accounts)}</select></div><div class="field"><label>${esc(t('Paid To'))} · ${esc(d.buyer.name)} *</label><select name="receiver_account_id" required>${payeeOptions(payees)}</select>${payees.length?'':`<small class="bad">Add a buyer receiver account first. <button type="button" class="btn small" onclick="managePayeeAccountsV330('excavator_buyer',${buyerId},'${esc(d.buyer.name)}')">Manage Accounts</button></small>`}</div><div class="field"><label>Reference *</label><input name="reference" required></div><div class="field"><label>Evidence *</label><input type="file" name="receipt" required></div><div class="field"><label>Reason *</label><textarea name="reason" required></textarea></div></div><input type="hidden" name="method" value="Bank"><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn danger" ${payees.length&&accounts.length?'':'disabled'}>Review & Refund</button></div></form>`,'wide');setAccountContext(document.querySelector('#modalRoot form'),{country:'Pakistan',currency:'PKR',direction:'payment'})}catch(e){toast(e.message)}};
window.saveRefundResaleCreditV330=async function(e,buyerId){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const fd=new FormData(f),ok=await confirmAction({title:'Refund Pakistan Resale Credit',message:'Verify both Pay From and Paid To accounts. This creates one outgoing Finance transaction.',confirmLabel:'Record Refund',tone:'danger',details:[{label:'Refund',value:pkr(fd.get('amount_pkr'))},{label:'Pay From',value:f.payment_account_id.selectedOptions[0]?.textContent||'—'},{label:'Paid To',value:f.receiver_account_id.selectedOptions[0]?.textContent||'—'},{label:'Reference',value:fd.get('reference')}]});if(!ok)return;try{await multipartApi(`/api/v330/excavator/buyers/${buyerId}/resale-credit/refund`,fd);closeModalAfterSave();toast('Pakistan resale credit refund recorded');openPakistanResalesV327(buyerId);scheduleDataSync?.()}catch(x){toast(x.message)}};

window.combinedResaleSettlementV330=async function(buyerId){try{const [d,s,accounts]=await Promise.all([api(`/api/v327/excavator/buyers/${buyerId}/pakistan-resales`),api(`/api/v330/excavator/buyers/${buyerId}/resale-credit-summary`),countryAccountsV327('Pakistan','receipt')]);modal(`<h2>${esc(t('Settle with Credit + New Payment'))}</h2><p class="muted">Use already-received resale credit and record only the additional new money as a Finance receipt.</p><form data-account-country="Pakistan" data-account-currency="PKR" data-account-direction="receipt" onsubmit="saveCombinedResaleSettlementV330(event,${buyerId})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>${esc(t('Use Existing Credit'))} (PKR)</label><input name="use_credit_pkr" type="number" min="0" max="${Number(s.available_credit_pkr||0)}" step="0.01" value="${Number(s.available_credit_pkr||0)}"></div><div class="field"><label>${esc(t('New Resale Payment'))} (PKR)</label><input name="new_payment_pkr" type="number" min="0" step="0.01" oninput="v330ToggleCombinedNew(this.form)"></div></div><div class="workspace-banner"><b>${esc(t('Available Credit'))}: ${pkr(s.available_credit_pkr)}</b></div>${targetRows(d.resales)}<div data-v330-new-money><div class="grid g2"><div class="field"><label>FX Rate to KRW *</label><input name="fx_rate_to_krw" type="number" min="0.000001" step="0.000001"></div><div class="field"><label>Payment Date *</label><input name="payment_date" type="date" value="${today()}"></div><div class="field"><label>Receive Into · Pakistan Company Account *</label><select name="payment_account_id">${accountOptionsV327(accounts)}</select></div><div class="field"><label>Reference *</label><input name="reference"></div><div class="field"><label>Receipt / Evidence *</label><input type="file" name="receipt"></div></div></div><input type="hidden" name="method" value="Bank"><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Review & Confirm</button></div></form>`,'wide');const f=document.querySelector('#modalRoot form');v330ToggleCombinedNew(f);setAccountContext(f,{country:'Pakistan',currency:'PKR',direction:'receipt'})}catch(e){toast(e.message)}};
window.v330ToggleCombinedNew=function(f){const n=Number(f.new_payment_pkr?.value||0),box=f.querySelector('[data-v330-new-money]');if(box)box.style.opacity=n>.005?'1':'.55';for(const name of ['fx_rate_to_krw','payment_date','payment_account_id','reference','receipt'])if(f.elements[name])f.elements[name].required=n>.005};
window.saveCombinedResaleSettlementV330=async function(e,buyerId){e.preventDefault();const f=e.target;v330ToggleCombinedNew(f);if(!f.reportValidity())return;const ids=[...f.querySelectorAll('[name="resale_id"]:checked')].map(x=>Number(x.value));if(!ids.length)return toast('Select at least one machine.');const fd=new FormData(f),credit=Number(fd.get('use_credit_pkr')||0),fresh=Number(fd.get('new_payment_pkr')||0);fd.set('resale_ids',JSON.stringify(ids));const ok=await confirmAction({title:'Review Pakistan Resale Settlement',message:'Existing credit is allocation only; only the new payment creates a Finance receipt.',confirmLabel:'Confirm Settlement',details:[{label:'Existing Credit Used',value:pkr(credit)},{label:'New Payment',value:pkr(fresh)},{label:'Selected Machines',value:String(ids.length)},{label:'Receive Into',value:f.payment_account_id?.selectedOptions?.[0]?.textContent||'—'}]});if(!ok)return;try{await multipartApi(`/api/v330/excavator/buyers/${buyerId}/resale-settlement`,fd);closeModalAfterSave();toast('Pakistan resale settlement completed');openPakistanResalesV327(buyerId);scheduleDataSync?.()}catch(x){toast(x.message)}};


function ensureDirectReceiverFieldsV330(form){
  if(!form||form.dataset.v330DirectReceiver==='1')return;
  const submit=String(form.getAttribute('onsubmit')||''),isCost=submit.includes('saveExcavatorCostV319'),isManual=!!form.querySelector('[name="source_type"][value="Manual"]');if(!isCost&&!isManual)return;
  form.dataset.v330DirectReceiver='1';const method=form.querySelector('[name="payment_method"]'),type=form.querySelector('[name="type"]');
  const anchor=(isCost?form.querySelector('[name="counterparty"]'):form.querySelector('[name="description"]'))?.closest('.field');if(!anchor)return;
  const box=document.createElement('div');box.dataset.v330DirectReceiverBox='1';box.className='card';box.style.marginTop='10px';box.innerHTML=`<h3 style="margin-top:0">${esc(t('Paid To'))} · ${esc(t('Receiver Account'))}</h3><div class="muted">${esc(t('Destination account is required for electronic outgoing payments.'))}</div><div class="grid g2"><div class="field"><label>${esc(t('Receiver / Payee Name'))}</label><input name="receiver_name"></div><div class="field"><label>${esc(t('Receiver Bank / Institution'))}</label><input name="receiver_bank_name"></div><div class="field"><label>${esc(t('Receiver Account Number'))}</label><input name="receiver_account_number"></div><div class="field"><label>${esc(t('Receiver Account Country'))}</label><input name="receiver_account_country" value="South Korea"></div><div class="field"><label>${esc(t('Receiver Currency'))}</label><select name="receiver_currency"><option>KRW</option><option>USD</option><option>PKR</option><option>EUR</option><option>JPY</option><option>CNY</option></select></div></div>`;
  anchor.insertAdjacentElement('afterend',box);
  if(isCost){const cp=form.querySelector('[name="counterparty"]');if(cp){box.querySelector('[name="receiver_name"]').value=cp.value||'';cp.addEventListener('input',()=>{if(!box.querySelector('[name="receiver_name"]').dataset.touched)box.querySelector('[name="receiver_name"]').value=cp.value});box.querySelector('[name="receiver_name"]').addEventListener('input',e=>e.target.dataset.touched='1')}const cur=form.querySelector('[name="payment_currency"]');if(cur){box.querySelector('[name="receiver_currency"]').value=cur.value||'KRW';cur.addEventListener('change',()=>box.querySelector('[name="receiver_currency"]').value=cur.value||'KRW')}}
  const update=()=>{const outgoing=isCost||(isManual&&String(type?.value||'').toLowerCase()!=='revenue'),electronic=/bank|card|cheque|check|wallet/i.test(method?.value||'');box.style.display=outgoing&&electronic?'block':'none';for(const n of ['receiver_name','receiver_account_number']){const el=box.querySelector(`[name="${n}"]`);if(el)el.required=outgoing&&electronic}}
  method?.addEventListener('change',update);type?.addEventListener('change',update);update();try{translateElement(box)}catch(_){ }
}
function enhancedContextV330(root=document){contextObserver(root);root.querySelectorAll?.('form').forEach(ensureDirectReceiverFieldsV330)}

window.BOMMutationHub.register('v330-context',enhancedContextV330);enhancedContextV330(document);
