function loadBuyer337(id,st,{force=false}={}){if(st.d&&!force)return Promise.resolve(st.d);if(st.detailPending)return st.detailPending;st.errors=st.errors||{};const epoch=Number(st.epoch||0);st.detailPending=Promise.resolve(api('/api/excavator/buyers/'+id)).then(d=>{if(epoch!==Number(st.epoch||0))return null;st.d=d;delete st.errors.d;renderBuyer337(id,{full:true});if(st.active==='accounts')ensureBuyerAccounts337(id);return d}).catch(e=>{if(epoch===Number(st.epoch||0)){st.errors.d=e?.message||String(e);renderBuyer337(id,{full:true})}return null}).finally(()=>{if(epoch===Number(st.epoch||0)){st.detailPending=null;buyerPending.delete(id)}});buyerPending.set(id,st.detailPending);return st.detailPending}
window.v337BuyerSection=function(id,active){id=Number(id);buyerActive.set(id,active);const st=buyerState.get(id);if(!st)return excavatorBuyerDetail(id);st.active=active;renderBuyer337(id);if(active==='accounts')ensureBuyerAccounts337(id)};
