window.BOMInvalidateProfilesV352=function(){
  const visible=document.getElementById('v324WorkflowSurface'),supplierId=Number(visible?.querySelector('[data-v337-supplier-tabs] button')?.getAttribute('onclick')?.match(/\((\d+)/)?.[1]||0),buyerId=Number(visible?.querySelector('[data-v337-buyer-tabs] button')?.getAttribute('onclick')?.match(/\((\d+)/)?.[1]||0);
  for(const st of supplierState.values()){st.epoch=Number(st.epoch||0)+1;st.md=null;st.requirements=null;st.statement=null;st.accounts=null;st.pending={};st.errors={}}
  for(const st of buyerState.values()){st.epoch=Number(st.epoch||0)+1;st.d=null;st.accounts=null;st.detailPending=null;st.accountsPending=null;st.errors={}}
  if(supplierId&&supplierState.has(supplierId)){const st=supplierState.get(supplierId);renderSupplier337(supplierId);for(const key of new Set(['md',...supplierNeeded337(st.active),...(st.active==='overview'||st.active==='payments'?['statement']:[])]))ensureSupplier337(supplierId,key)}
  if(buyerId&&buyerState.has(buyerId)){const st=buyerState.get(buyerId);renderBuyer337(buyerId);void loadBuyer337(buyerId,st,{force:true});if(st.active==='accounts')void ensureBuyerAccounts337(buyerId,{force:true})}
};


