let accountState338=null;
async function accounts338(type,id,archived=false){return api('/api/v338/payee-accounts?'+new URLSearchParams({business_unit_id:String(bu()),entity_type:type,entity_id:String(id),include_archived:archived?'1':'0'}))}
async function history338(type,id){return api('/api/v338/payee-account-history?'+new URLSearchParams({business_unit_id:String(bu()),entity_type:type,entity_id:String(id)}))}
function accTypeTitle(type){return type==='excavator_supplier'?'Supplier Accounts':type==='excavator_buyer'?'Buyer Accounts':'Receiver / Payee Accounts'}
function accountForm338(s,row){const edit=!!row;return `<div class="card" style="margin-top:12px"><h3 style="margin-top:0">${esc(t(edit?'Edit Account':'Add Receiver Account'))}</h3><form onsubmit="v338SaveAccount(event)"><input type="hidden" name="account_id" value="${edit?Number(row.id):0}"><div class="grid g2"><div class="field"><label>Label *</label><input name="label" required value="${esc(row?.label||'')}"></div><div class="field"><label>Method *</label><select name="method_type" onchange="v338AccountMethodChanged(this.form)">${['Bank','Card','Wallet','Other'].map(x=>`<option ${String(row?.method_type||'Bank')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Bank / Institution <span data-v338-bank-star>*</span></label><input name="bank_name" value="${esc(row?.bank_name||'')}" placeholder="${esc(t('e.g., KB Kookmin Bank'))}"></div><div class="field"><label>Account Holder</label><input name="account_holder" value="${esc(row?.account_holder||'')}" placeholder="${esc(t('e.g., Kim Min-su'))}"></div><div class="field"><label>Account Number ${edit?'':'*'}</label><input name="account_number" inputmode="numeric" pattern="[0-9 -]{4,40}" title="Use numbers, spaces or hyphens only (minimum 4 characters)." ${edit?'':`required`} placeholder="${edit?`Leave blank to keep ${esc(row?.account_number_masked||'saved number')}`:''}"></div><div class="field"><label>Account Country</label><input name="account_country" value="${esc(row?.account_country||'')}" placeholder="${esc(t('e.g., South Korea'))}"></div><div class="field"><label>Currency</label><select name="currency">${['KRW','PKR','USD','EUR','JPY','CNY'].map(x=>`<option ${String(row?.currency||'KRW').toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label><input type="checkbox" name="is_default" value="1" ${Number(row?.is_default||0)?'checked':''}> Default account</label></div><div class="field" style="grid-column:1/-1"><label>${esc(t('Change Reason'))} ${edit?'*':''}</label><input name="reason" ${edit?'required':''} placeholder="${edit?'Why is this account being changed?':'Optional note'}"></div></div><div class="actions"><button type="button" class="btn" onclick="v338CancelAccountEdit()">${esc(t(edit?'Cancel Edit':'Clear'))}</button><button class="btn primary" type="submit">${esc(t(edit?'Update Account':'Save Account'))}</button></div></form></div>`}
function accountRows338(rows){return `<div class="v337-account-list">${rows.map(a=>`<div class="v338-account-row ${Number(a.active||0)?'':'archived'}"><div><b>${esc(a.label||'Account')}</b><div class="muted">${esc(a.account_holder||'')}</div></div><div>${esc(a.bank_name||a.method_type||'')}<div class="muted">${esc(a.account_country||'—')} · ${esc(a.currency||'—')} · ${esc(a.account_number_masked||'')}</div></div><div>${Number(a.is_default||0)?'<span class="pill good">Default</span>':''}${!Number(a.active||0)?'<span class="pill">Archived</span>':''}<div class="muted">${Number(a.usage_count||0)} historical link(s)</div></div><div class="v338-account-actions">${Number(a.active||0)?`<button class="btn small" onclick="v338EditAccount(${Number(a.id)})">${esc(t('Edit'))}</button><button class="btn small danger" onclick="v338ArchiveAccount(${Number(a.id)})">${esc(t('Archive'))}</button>`:''}</div></div>`).join('')||'<div class="empty">No receiver accounts saved yet.</div>'}</div>`}
function historyHtml338(rows){return `<div class="card" style="margin-top:12px"><h3>${esc(t('Account History'))}</h3><div class="v338-history">${rows.map(h=>`<div class="v338-history-row"><b>${esc(h.action||'Changed')} · Account #${Number(h.account_id)}</b><small>${esc(h.created_at||'')} · ${esc(h.changed_by_name||'User')}${h.reason?' · '+esc(h.reason):''}</small></div>`).join('')||'<div class="empty">No account changes recorded yet.</div>'}</div></div>`}
async function renderAccountManager338(){if(!accountState338)return;const [rows,hist]=await Promise.all([accounts338(accountState338.type,accountState338.id,true),history338(accountState338.type,accountState338.id)]);accountState338.rows=rows;const edit=rows.find(x=>Number(x.id)===Number(accountState338.editId)&&Number(x.active||0));const box=document.querySelector('#modalRoot .modal');if(!box)return;box.innerHTML=`<div class="v337-account-manager"><div class="section-title"><div><h2>${esc(t(accTypeTitle(accountState338.type)))}</h2><div class="muted">${esc(accountState338.name)} · shared receiver/payee account management.</div></div><button class="btn" onclick="v338CloseAccountManager()">${esc(t('Close'))}</button></div>${accountRows338(rows)}${accountForm338(accountState338,edit)}${historyHtml338(hist)}<div class="muted" style="margin-top:8px">Used accounts are archived, not deleted. Historical Finance snapshots remain unchanged when account master data is edited.</div></div>`;v338AccountMethodChanged(box.querySelector('form[onsubmit*="v338SaveAccount"]'));try{translateElement(box)}catch(_){}}
async function refreshParentSelectors338(state){if(!state)return;const host=document.getElementById('v324WorkflowSurface')||document.querySelector('#modalRoot .modal')||document;let rows=[];try{rows=await accounts338(state.type,state.id,false)}catch(_){return}for(const sel of host.querySelectorAll('[name="receiver_account_id"],[name="token_receiver_account_id"]')){const old=String(sel.value||''),preferred=String(state.lastSavedId||old||(rows.find(x=>Number(x.is_default||0))?.id||''));sel.innerHTML='<option value="">Select saved receiver account</option>'+rows.map(x=>`<option value="${Number(x.id)}">${esc(x.label||'Account')} · ${esc(x.bank_name||x.method_type||'')} · ${esc(x.currency||'')} ${esc(x.account_number_masked||'')}</option>`).join('');if(preferred&&rows.some(x=>String(x.id)===preferred))sel.value=preferred;sel.dispatchEvent(new Event('change',{bubbles:true}))}}
window.openCounterpartyAccountsV338=async function(type,id,name='Payee'){if(!Number(id))return toast('Select the buyer or supplier first.');accountState338={type:txt(type),id:Number(id),name:txt(name)||'Payee',editId:0,lastSavedId:0};modal('<div class="empty">Loading accounts…</div>','wide');try{await renderAccountManager338()}catch(e){toast(e.message)}};
window.openCounterpartyAccountsV337=window.openCounterpartyAccountsV338;window.managePayeeAccountsV330=window.openCounterpartyAccountsV338;try{managePayeeAccountsV330=window.openCounterpartyAccountsV338}catch(_){ }
window.v338EditAccount=async id=>{if(!accountState338)return;accountState338.editId=Number(id);await renderAccountManager338()};
window.v338CancelAccountEdit=async()=>{if(!accountState338)return;accountState338.editId=0;await renderAccountManager338()};
window.v338AccountMethodChanged=function(f){if(!f)return;const bank=String(f.method_type?.value||'Bank')==='Bank';if(f.bank_name)f.bank_name.required=bank;if(f.account_number)f.account_number.required=bank&&!Number(f.account_id?.value||0);const star=f.querySelector('[data-v338-bank-star]');if(star)star.style.display=bank?'inline':'none'};
window.v338SaveAccount=async function(e){e.preventDefault();const f=e.target;if(!accountState338||!f.reportValidity())return;const body=Object.fromEntries(new FormData(f).entries()),id=Number(body.account_id||0);Object.assign(body,{business_unit_id:bu(),entity_type:accountState338.type,entity_id:accountState338.id,is_default:!!f.is_default?.checked});delete body.account_id;try{const r=await api(id?`/api/v338/payee-accounts/${id}`:'/api/v338/payee-accounts',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});accountState338.lastSavedId=Number(r.id||r.account?.id||id||0);accountState338.editId=0;toast(id?'Receiver account updated':'Receiver account saved');try{await refreshProfileAccounts337(accountState338.type,accountState338.id)}catch(_){}await v338CloseAccountManager()}catch(x){toast(x.message)}};
window.v338ArchiveAccount=async function(id){if(!accountState338)return;const row=(accountState338.rows||[]).find(x=>Number(x.id)===Number(id));const reason=await reasonAction({title:'Archive Receiver Account',message:`Archive ${row?.label||'this account'}? It will no longer be selectable, but historical transactions remain unchanged.`,confirmLabel:'Archive',tone:'danger',placeholder:'Reason for archiving'});if(reason===null)return;try{await api(`/api/v338/payee-accounts/${Number(id)}/archive`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});toast('Receiver account archived');await renderAccountManager338();try{await refreshProfileAccounts337(accountState338.type,accountState338.id)}catch(_){}}catch(e){toast(e.message)}};
window.v338CloseAccountManager=function(){const state=accountState338?{...accountState338}:null;accountState338=null;closeModal(true);setTimeout(()=>refreshParentSelectors338(state).catch(()=>{}),0)};
window.v337CloseAccountManager=window.v338CloseAccountManager;

/* ---------------- Pakistan Resales: Buyer-profile-style sections ---------------- */
const resaleState338=new Map(),resaleActive338=new Map();
const resaleTabs338=['overview','records','payments','credit','refunds','transfers','documents'];
const resaleLabels338={overview:'Overview',records:'Resale Records',payments:'Payments & Settlements',credit:'Credit',refunds:'Refunds',transfers:'Pakistan → Korea Bank Transfers',documents:'Documents'};
function resaleTabsHtml338(id,active){return `<div class="v338-resale-tabs" data-v338-resale-tabs>${resaleTabs338.map(k=>`<button type="button" class="btn ${active===k?'active':''}" onclick="v338PakistanSection(${id},'${k}')">${esc(t(resaleLabels338[k]))}</button>`).join('')}</div>`}
function resaleRecord338(r,id){return `<div class="v338-record"><div class="v338-record-grid"><div><b>${esc(r.asset_no||'')} · ${esc(r.machine_name||((r.make||'')+' '+(r.model||'')).trim()||'Machine')}</b><small>${esc(r.resale_date||'—')} · Korea sale ${krw338(r.selling_price)}</small></div><div><small>Resale Price</small><b>${pkr338(r.resale_price_pkr)}</b></div><div><small>Our Share</small><b>${pkr338(r.our_share_pkr)}</b></div><div><small>Outstanding</small><b>${pkr338(r.outstanding_pkr)}</b><small>${esc(r.settlement_status||'')}</small></div></div><div class="actions">${r.resale_evidence_file?`<a class="btn small" target="_blank" href="/uploads/${encodeURIComponent(r.resale_evidence_file)}">${esc(t('View Evidence'))}</a>`:''}${r.settlement_status!=='Voided'?`<button class="btn small" onclick="pakistanResaleFormV327(${id},${r.id})">${esc(t('Edit'))}</button><button class="btn small danger" onclick="voidPakistanResaleV327(${id},${r.id})">${esc(t('Void'))}</button>`:''}</div></div>`}
function payment338(p,id){return `<div class="v338-record"><div class="v338-record-grid"><div><b>Pakistan Resale Payment #${Number(p.id)}</b><small>${esc(p.payment_date||'—')} · ${esc(p.status||'Active')} · ${esc(p.payment_account_name||'—')}</small></div><div><small>Payment</small><b>${pkr338(p.amount_pkr)}</b></div><div><small>Allocated</small><b>${pkr338(p.allocated_pkr)}</b></div><div><small>Unallocated Credit</small><b>${pkr338(p.unallocated_pkr)}</b></div></div><div class="actions">${p.receipt_url?`<a class="btn small" target="_blank" href="${esc(p.receipt_url)}">Receipt</a>`:''}${p.status==='Active'?`<button class="btn small" onclick="reallocateResalePaymentV327(${id},${p.id})">Reallocate</button><button class="btn small danger" onclick="voidResalePaymentV327(${id},${p.id})">Void Payment</button>`:''}</div></div>`}
function transfer338(x){return `<div class="v338-record"><div class="v338-record-grid"><div><b>${esc(x.from_account_name||'Pakistan Account')} → ${esc(x.to_account_name||'Korea Account')}</b><small>${esc(x.transfer_date||'—')} · ${esc(x.reference||'')}</small></div><div><small>Source</small><b>${pkr338(x.source_amount_pkr)}</b></div><div><small>Destination</small><b>${krw338(x.destination_amount_krw)}</b></div><div><small>Bank Fee</small><b>${pkr338(x.bank_fee_pkr)}</b><small>${esc(x.status||'Active')}</small></div></div><div class="actions">${x.evidence_url?`<a class="btn small" target="_blank" href="${esc(x.evidence_url)}">Evidence</a>`:''}${x.status==='Active'?`<button class="btn small danger" onclick="voidPakistanKoreaTransferV327(${x.id})">Void</button>`:''}</div></div>`}
function resaleDocs338(st){const docs=[];for(const r of st.d.resales||[])if(r.resale_evidence_file)docs.push({title:`Resale Evidence · ${r.asset_no||r.id}`,url:'/uploads/'+r.resale_evidence_file,date:r.resale_date});for(const p of st.d.payments||[])if(p.receipt_url)docs.push({title:`Resale Payment Receipt #${p.id}`,url:p.receipt_url,date:p.payment_date});for(const r of st.refunds||[])if(r.receipt_url)docs.push({title:`${r.refund_type} #${r.id}`,url:r.receipt_url,date:r.refund_date});for(const x of st.d.transfers||[])if(x.evidence_url)docs.push({title:`Pakistan → Korea Transfer #${x.id}`,url:x.evidence_url,date:x.transfer_date});for(const x of st.buyerDetail?.documents||[])if(/pakistan|resale|refund/i.test(String(x.title||'')))docs.push({title:x.title||'Buyer Document',url:x.file_path,date:x.created_at});return `<div class="v338-doc-grid">${docs.map(x=>`<div class="v338-record"><b>${esc(x.title)}</b><small>${esc(x.date||'')}</small><div class="actions"><a class="btn small" target="_blank" href="${esc(x.url)}">Open</a></div></div>`).join('')||'<div class="empty">No Pakistan resale documents yet.</div>'}</div>`}
function resaleBody338(id,active,st){const d=st.d,s=d.summary||{},c=st.credit||{};if(active==='records')return `<div class="section-title"><div><h3>Pakistan Resale Records</h3><div class="muted">Resale facts remain separate from cash receipts.</div></div><button class="btn primary" onclick="pakistanResaleFormV327(${id},0)">+ Add Resale Record</button></div>${(d.resales||[]).map(r=>resaleRecord338(r,id)).join('')||'<div class="empty">No Pakistan resale records yet.</div>'}`;if(active==='payments')return `<div class="section-title"><div><h3>Payments & Settlements</h3><div class="muted">One real receipt remains one Finance transaction; allocations may cover multiple machines.</div></div><button class="btn primary" onclick="resaleProfitPaymentFormV327(${id})">+ Record Resale Profit Payment</button></div><div class="v327-account-note"><b>Pakistan account control:</b> receipts use active Pakistan PKR company bank accounts only.</div>${(d.payments||[]).map(p=>payment338(p,id)).join('')||'<div class="empty">No resale-profit payments yet.</div>'}`;if(active==='credit')return `<div class="section-title"><div><h3>Credit</h3><div class="muted">Unallocated money already received. Allocating credit creates no duplicate Finance receipt.</div></div><div class="actions"><button class="btn" onclick="allocateResaleCreditV330(${id})" ${num(c.available_credit_pkr)>.005?'':'disabled'}>Allocate Credit</button><button class="btn primary" onclick="combinedResaleSettlementV330(${id})">Settle with Credit + New Payment</button></div></div><div class="v338-grid-stats"><div class="v338-stat"><small>Total Received</small><b>${pkr338(c.total_received_pkr)}</b></div><div class="v338-stat"><small>Allocated</small><b>${pkr338(c.allocated_pkr)}</b></div><div class="v338-stat"><small>Refunded</small><b>${pkr338(c.refunded_pkr)}</b></div><div class="v338-stat"><small>Available Credit</small><b>${pkr338(c.available_credit_pkr)}</b></div></div>${(d.payments||[]).filter(p=>num(p.unallocated_pkr)>.005).map(p=>`<div class="v338-record"><b>Credit source · Payment #${p.id}</b><div class="muted">${esc(p.payment_date||'')} · ${pkr338(p.unallocated_pkr)} available</div></div>`).join('')||'<div class="empty">No unallocated resale credit.</div>'}`;if(active==='refunds')return `<div class="section-title"><div><h3>Refunds</h3><div class="muted">Outgoing refunds are separate real Finance payments and preserve their source-credit history.</div></div><button class="btn danger" onclick="refundResaleCreditV330(${id})" ${num(c.available_credit_pkr)>.005?'':'disabled'}>Refund Credit</button></div>${(st.refunds||[]).map(r=>`<div class="v338-record"><div class="v338-record-grid"><div><b>${esc(r.refund_type||'Refund')} #${Number(r.id)}</b><small>${esc(r.refund_date||'—')} · ${esc(r.status||'Completed')}</small></div><div><small>Amount</small><b>${pkr338(r.amount_pkr)}</b></div><div><small>KRW</small><b>${krw338(r.krw_amount)}</b></div><div><small>Reference</small><b>${esc(r.reference||'—')}</b></div></div><div class="muted">${esc(r.reason||'')}</div>${r.receipt_url?`<div class="actions"><a class="btn small" target="_blank" href="${esc(r.receipt_url)}">Receipt</a></div>`:''}</div>`).join('')||'<div class="empty">No Pakistan resale refunds recorded yet.</div>'}`;if(active==='transfers')return `<div class="section-title"><div><h3>Pakistan → Korea Bank Transfers</h3><div class="muted">Cash movement only. It does not create new Pakistan resale income.</div></div><button class="btn primary" onclick="pakistanKoreaTransferFormV327(${id})">Transfer Pakistan Funds to Korea</button></div>${(d.transfers||[]).map(transfer338).join('')||'<div class="empty">No Pakistan-to-Korea bank transfers recorded yet.</div>'}`;if(active==='documents')return `<div class="section-title"><div><h3>Documents</h3><div class="muted">Resale evidence, receipts, refunds and transfer evidence.</div></div></div>${resaleDocs338(st)}`;return `<div class="v338-grid-stats"><div class="v338-stat"><small>Total Share Due</small><b>${pkr338(s.total_share_due_pkr)}</b></div><div class="v338-stat"><small>Received / Allocated</small><b>${pkr338(s.received_allocated_pkr)}</b></div><div class="v338-stat"><small>Outstanding</small><b>${pkr338(s.outstanding_pkr)}</b></div><div class="v338-stat"><small>Available Credit</small><b>${pkr338(c.available_credit_pkr??s.unallocated_credit_pkr)}</b></div><div class="v338-stat"><small>Resold Machines</small><b>${Number(s.resold_machines||0)}</b></div><div class="v338-stat"><small>Settled Machines</small><b>${Number(s.settled_machines||0)}</b></div><div class="v338-stat"><small>Payments</small><b>${(d.payments||[]).length}</b></div><div class="v338-stat"><small>Transfers</small><b>${(d.transfers||[]).length}</b></div></div><div class="card" style="margin-top:12px"><b>Accounting separation remains enforced.</b><div class="muted">Pakistan resale profit/share is not combined with Korea machine-sale profit. Pakistan-to-Korea transfers move cash only.</div></div>`}
window.v338PakistanSection=function(id,active){active=resaleTabs338.includes(active)?active:'overview';resaleActive338.set(Number(id),active);const st=resaleState338.get(Number(id));if(!st)return openPakistanResalesV327(id);st.active=active;const tabs=document.querySelector('[data-v338-resale-tabs]');if(tabs)tabs.outerHTML=resaleTabsHtml338(id,active);const body=document.getElementById('v338PakistanResaleBody');if(body){body.innerHTML=resaleBody338(id,active,st);try{translateElement(body)}catch(_){}}};
window.openPakistanResalesV327=async function(buyerId){buyerId=Number(buyerId);window.__v327BuyerId=buyerId;try{const [d,credit,refunds,buyerDetail]=await Promise.all([api(`/api/v327/excavator/buyers/${buyerId}/pakistan-resales`),api(`/api/v330/excavator/buyers/${buyerId}/resale-credit-summary`),api(`/api/v338/excavator/buyers/${buyerId}/resale-refunds`),api(`/api/excavator/buyers/${buyerId}`)]),active=resaleActive338.get(buyerId)||resaleState338.get(buyerId)?.active||'overview',st={d,credit,refunds,buyerDetail,active};resaleState338.set(buyerId,st);resaleActive338.set(buyerId,active);openWorkflowHtmlV324(`<div class="section-title"><div><div class="muted">${esc(t('Pakistan Resales'))}</div><h2 style="margin:2px 0">${esc(d.buyer.name)}</h2><div>${esc(d.buyer.country||'Pakistan')} · Pakistan resale profit is accounted separately from Korea machine-trading profit.</div></div><div class="actions"><button class="btn" onclick="excavatorBuyerDetail(${buyerId})">← ${esc(t('Buyer Details'))}</button>${typeof v284ResaleStatement==='function'?`<button class="btn" onclick="v284ResaleStatement(${buyerId})">${esc(t('View Statement'))}</button>`:''}</div></div>${resaleTabsHtml338(buyerId,active)}<div class="card"><div id="v338PakistanResaleBody" class="v338-resale-body">${resaleBody338(buyerId,active,st)}</div></div>`);try{translateElement(document.getElementById('v324WorkflowSurface'))}catch(_){}}catch(e){toast(e.message)}};

/* ---------------- Finance + Accounting collapsible filters ---------------- */
const filterState338={finance:{collapsed:true,values:{}},posting:{collapsed:true,values:{}}};
const filterIds338={finance:['financeSearch','financeStatusFilter','financeTypeFilter','financeEvidenceFilter','v335FinanceFrom','v335FinanceTo'],posting:['v318PostingSearch','v335PostingFrom','v335PostingTo']};
function activeCount338(kind){return filterIds338[kind].reduce((n,id)=>n+(txt(document.getElementById(id)?.value)?1:0),0)}
function captureFilter338(kind){for(const id of filterIds338[kind]){const el=document.getElementById(id);if(el)filterState338[kind].values[id]=el.value}updateFilterHeader338(kind)}
function restoreFilter338(kind){for(const id of filterIds338[kind]){const el=document.getElementById(id),v=filterState338[kind].values[id];if(el&&v!==undefined&&el.value!==v)el.value=v}}
function updateFilterHeader338(kind){const row=document.querySelector(`[data-v338-filter-toggle="${kind}"]`);if(!row)return;const n=activeCount338(kind);const b=row.querySelector('button'),c=row.querySelector('.v338-filter-count');if(b)b.textContent=t(filterState338[kind].collapsed?'Show Filters':'Hide Filters');if(c)c.textContent=n?`${n} ${t('Active filters')}`:t('Filters')}
window.v338ToggleFilters=function(kind){const st=filterState338[kind];if(!st)return;st.collapsed=!st.collapsed;const body=document.querySelector(`[data-v338-filter-body="${kind}"]`);body?.classList.toggle('v338-collapsed',st.collapsed);updateFilterHeader338(kind)};
function upgradeFilter338(kind,body){if(!body||body.dataset.v338Upgraded==='1')return;body.dataset.v338Upgraded='1';body.dataset.v338FilterBody=kind;body.classList.add('v338-collapsible-filter-body');if(kind==='posting'){body.classList.add('v338-posting-filter');const status=body.querySelector('.v318-control-tabs')||body.closest('.card')?.querySelector('.v318-control-tabs');if(status){let row=body.parentElement.querySelector('[data-v338-posting-status]');if(!row){row=document.createElement('div');row.className='v338-posting-status-row';row.dataset.v338PostingStatus='1';body.before(row)}row.appendChild(status)}body.querySelector('.v337-filter-status')?.remove()}
  const toggle=document.createElement('div');toggle.className='v338-filter-toggle-row';toggle.dataset.v338FilterToggle=kind;toggle.innerHTML=`<button type="button" class="btn" onclick="v338ToggleFilters('${kind}')"></button><span class="v338-filter-count"></span>`;body.before(toggle);restoreFilter338(kind);body.classList.toggle('v338-collapsed',filterState338[kind].collapsed);for(const id of filterIds338[kind]){const el=document.getElementById(id);if(el&&!el.dataset.v338State){el.dataset.v338State='1';el.addEventListener('input',()=>captureFilter338(kind));el.addEventListener('change',()=>captureFilter338(kind))}}updateFilterHeader338(kind)}
function upgradeFilters338(){upgradeFilter338('finance',document.querySelector('#financeRecordsPanel .finance-filterbar.v337-filter-shell'));upgradeFilter338('posting',document.querySelector('.v337-posting-shell'))}

